(window.NTDATA=window.NTDATA||{});(NTDATA.arar=NTDATA.arar||{}).jn={"1":{"1":"Սկզբում էր Բանը, և Բանն Աստծու մոտ էր, և Բանն Աստված էր։","2":"Նա սկզբում Աստծու մոտ էր։","3":"Ամեն ինչ նրանով եղավ, և առանց նրա ոչինչ չեղավ, ինչ որ եղավ։","4":"Կյանքը նրանով էր, և կյանքը մարդկանց լույսն էր։","5":"Եվ լույսը խավարի մեջ լուսավորում է, իսկ խավարը նրան չտիրեց։","6":"Կար մի մարդ՝ ուղարկված Աստծու կողմից, և նրա անունը Հովհաննես էր։","7":"Նա եկավ որպես վկա՝ Լույսի մասին վկայելու, որ նրա միջոցով բոլորը հավատան։","8":"Նա Լույսը չէր, այլ եկել էր Լույսի մասին վկայելու։","9":"Ճշմարիտ Լույսն էր, որ լուսավորում է ամեն մարդու, որ աշխարհ է գալիս։","10":"Նա աշխարհի մեջ էր, և աշխարհը նրանով արարվեց, սակայն աշխարհը նրան չճանաչեց։","11":"Յուրայինների մոտ եկավ, բայց յուրայինները նրան չընդունեցին։","12":"Սակայն նրանց, ովքեր ընդունեցին նրան և հավատացին նրա անվանը, իշխանություն տվեց Աստծու որդիները լինելու։","13":"Նրանք չծնվեցին արյունից, ո՛չ էլ մարմնի ու մարդու կամքից, այլ ծնվեցին Աստծուց։","14":"Եվ Բանը մարմին դարձավ ու մեր մեջ բնակվեց, և տեսանք նրա փառքը. փառք, որ Հորից ունի Միածինը՝ լի շնորհով ու ճշմարտությամբ։","15":"Հովհաննեսը նրա մասին վկայում է ու աղաղակելով ասում. «Սա էր, որի մասին ասացի. \"Նա, որ գալիս է ինձանից հետո, ինձանից ավելի մեծ է, որովհետև ինձանից առաջ էր\"»։","16":"Եվ նրա լիությունից մենք բոլորս շնորհի վրա շնորհը ստացանք.","17":"որովհետև օրենքը Մովսեսի միջոցով տրվեց, իսկ շնորհն ու ճշմարտությունը Հիսուս Քրիստոսի միջոցով եղան։","18":"Աստծուն ոչ ոք երբեք չի տեսել, բացի միածին Որդուց, որ Հոր ծոցում է. նա՛ է մեզ նրա մասին հայտնել։","19":"Եվ այս է Հովհաննեսի վկայությունը. երբ հրեաները Երուսաղեմից նրա մոտ քահանաների ու ղևտացիների ուղարկեցին, որպեսզի նրան հարցնեն. «Դու ո՞վ ես»,","20":"նա խոստովանեց և չուրացավ. խոստովանեց, թե՝ «Ես Քրիստոսը չեմ»։","21":"Եվ նրան հարցրին. «Հապա ո՞վ, Եղիա՞ն ես»։ Նա ասաց. «Ոչ, չեմ»։ «Մարգարե՞ն ես դու»։ Նա պատասխանեց. «Ո՛չ»։","22":"Արդ նրան ասացին. «Հապա ո՞վ ես, որ մեզ ուղարկողներին պատասխանենք. ի՞նչ ես ասում քո մասին»։","23":"Ասաց. «Ես անապատում կանչողի ձայնն եմ. \"Հարթե՛ք Տիրոջ ճանապարհը\"» (Ես. 40.3), ինչպես Եսայի մարգարեն ասաց։","24":"Եվ ուղարկվածները փարիսեցիներից էին։","25":"Նրան հարցրին ու ասացին. «Հապա ինչո՞ւ ես մկրտում, եթե դու ո՛չ Քրիստոսն ես, ո՛չ Եղիան, ո՛չ էլ մարգարեն»։","26":"Հովհաննեսը նրանց պատասխանեց. «Ես ջրով եմ մկրտում, բայց ձեր մեջ կա մեկը, որին դուք չեք ճանաչում։","27":"Նա, որ գալիս է ինձանից հետո և որ ինձանից էլ առաջ է եղել, որի կոշիկների կապերն արձակելու արժանի չեմ ես»։","28":"Այս բանը պատահեց Բեթանիայում՝ Հորդանանի մյուս կողմում, որտեղ Հովհաննեսը մկրտում էր։","29":"Հաջորդ օրը Հովհաննեսը տեսավ Հիսուսին, որ գալիս էր իր մոտ, ու ասաց. «Ահա Աստծու Գառը, որ իր վրա է վերցնում աշխարհի մեղքը։","30":"Սա է, որի մասին ես ասում էի. \"Ինձանից հետո գալիս է մեկը, որ ինձանից մեծ է, որովհետև նա կար ինձանից առաջ։","31":"Ես չէի ճանաչում նրան։ Սակայն որպեսզի նա հայտնի լինի Իսրայելին, դրա համար եկա ջրով մկրտելու\"»։","32":"Եվ Հովհաննեսը վկայեց ու ասաց. «Տեսնում էի Հոգին, որ աղավնու պես իջնում էր երկնքից և հանգչում նրա վրա։","33":"Ես նրան չէի ճանաչում, բայց նա, ով ինձ ուղարկեց ջրով մկրտելու, ինձ ասաց. \"Ում վրա տեսնես, որ Հոգին իջնում է ու մնում, նա՛ է Սուրբ Հոգով մկրտողը\"։","34":"Ու ես տեսա և վկայեցի, թե՝ \"Սա է Աստծու Որդին\"»։","35":"Հաջորդ օրը Հովհաննեսը իր երկու աշակերտների հետ դարձյալ կանգնած էր։","36":"Եվ տեսնելով Հիսուսին, որ գալիս էր, ասաց. «Ահա Աստծու Գառը»։","37":"Եվ երկու աշակերտները նրանից լսեցին, ինչ որ ասաց, ու գնացին Հիսուսի հետևից։","38":"Հիսուսը շրջվեց, տեսավ նրանց, որ գալիս էին իր հետևից, ու նրանց ասաց. «Ի՞նչ եք ուզում»։ Նրանք ասացին նրան. «Ռա՛բբի (որ նշանակում է \"վարդապետ\"), որտե՞ղ ես մնում»։","39":"Նրանց ասաց. «Եկե՛ք ու տեսե՛ք»։ Եկան ու տեսան, թե որտե՛ղ էր մնում։ Այդ օրը նրա մոտ մնացին, որովհետև տասներորդ ժամն էր։","40":"Սիմոն Պետրոսի եղբայրը՝ Անդրեասը, մեկն էր այն երկուսից, որոնք լսեցին Հովհաննեսից ու նրա հետևից գնացին։","41":"Սա նախ գտնում է իր եղբայր Սիմոնին ու նրան ասում. «Գտանք Մեսիային (որ \"Քրիստոս\" է նշանակում)»։","42":"Եվ նրան տարավ Հիսուսի մոտ։ Հիսուսը նրան նայեց ու ասաց. «Դու Սիմոնն ես՝ Հովնանի որդին, դու պիտի կոչվես Կեփաս (որ \"Պետրոս\" է նշանակում)»։","43":"Հաջորդ օրը Հիսուսը ցանկացավ Գալիլեա գնալ։ Նա գտավ Փիլիպպոսին ու նրան ասաց. «Արի՛ իմ հետևից»։","44":"Փիլիպպոսն էլ Բեթսայիդայից էր՝ Անդրեասի ու Պետրոսի քաղաքից։","45":"Փիլիպպոսը գտավ Նաթանայելին ու նրան ասաց. «Գտանք նրան, ում մասին Մովսեսը օրենքի մեջ և մարգարեները գրել են։ Դա Հիսուսն է՝ Հովսեփի որդին Նազարեթից»։","46":"Եվ Նաթանայելը նրան ասաց. «Հնարավո՞ր է, որ Նազարեթից որևէ լավ բան դուրս գա»։ Փիլիպպոսը նրան ասաց. «Արի՛ և տե՛ս»։","47":"Հիսուսը տեսավ Նաթանայելին իր մոտ գալիս ու նրա մասին ասաց. «Ահա իսկական իսրայելացի, որի մեջ նենգություն չկա»։","48":"Նաթանայելը նրան ասաց. «Որտեղի՞ց ես ճանաչում ինձ»։ Հիսուսը պատասխանեց նրան. «Նախքան Փիլիպպոսի՝ քեզ կանչելը տեսա քեզ՝ թզենու տակ կանգնած»։","49":"Նաթանայելն ասաց. «Ռա՛բբի, դու ես Աստծու Որդին, դու ես Իսրայելի թագավորը»։","50":"Հիսուսը պատասխանեց և նրան ասաց. «Հավատում ես, որովհետև քեզ ասացի, թե թզենու տակ տեսել եմ քեզ. դրանից է՛լ ավելի մեծ բաներ պիտի տեսնես»։","51":"Եվ նրան ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. պիտի տեսնեք երկինքը բացված և Աստծու հրեշտակներին, որ բարձրանում և իջնում են Մարդու Որդու վրա»։"},"2":{"1":"Երրորդ օրը Գալիլեայի Կանա քաղաքում հարսանիք կար։ Այնտեղ էր նաև Հիսուսի մայրը։","2":"Հիսուսը և իր աշակերտները ևս հարսանիքի հրավիրվեցին։","3":"Եվ երբ գինին պակասեց, Հիսուսի մայրը նրան ասաց. «Գինի չունեն»։","4":"Հիսուսը նրան ասաց. «Դու ինձ հետ ի՞նչ գործ ունես, ո՛վ կին. իմ ժամանակը դեռ չի հասել»։","5":"Նրա մայրն սպասավորներին ասաց. «Ինչ որ ձեզ ասի, արե՛ք»։","6":"Հրեաների սրբվելու սովորության համաձայն՝ այնտեղ կային քարե վեց կարասներ, որոնցից յուրաքանչյուրը երկու կամ երեք մար էր տանում։","7":"Հիսուսը նրանց ասաց. «Այդ կարասները ջրո՛վ լցրեք»։ Եվ բերնեբերան լցրեցին։","8":"Եվ նրանց ասաց. «Հիմա վերցրե՛ք ու սեղանապետի՛ն տարեք»։ Նրանք տարան։","9":"Եվ երբ սեղանապետը համտեսեց գինի դարձած ջուրը՝ չիմանալով, թե որտեղի՛ց է (բայց սպասավորները, որ ջուր էին լցրել, գիտեին), կանչեց փեսային","10":"և նրան ասաց. «Ամեն մարդ նախ լավ գինին է մատուցում, և երբ հարբում են, այն ժամանակ՝ վատը։ Իսկ դու լավ գինին մինչև հիմա պահել ես»։","11":"Գալիլեայի Կանա քաղաքում դրվեց Հիսուսի կատարած հրաշքների սկիզբը։ Այսպես նա հայտնեց իր փառքը, և նրա աշակերտները հավատացին նրան։","12":"Դրանից հետո Հիսուսն իջավ Կափառնաում իր մոր, իր եղբայրների ու աշակերտների հետ, և մի քանի օր մնացին այնտեղ։","13":"Մոտենում էր հրեաների Զատիկը։ Հիսուսը բարձրացավ Երուսաղեմ։","14":"Եվ տաճարում տեսավ արջառներ, ոչխարներ ու աղավնիներ վաճառողների, ինչպես նաև լումայափոխների, որոնք նստած էին։","15":"Հիսուսը պարանից խարազան շինեց ու բոլորին տաճարից դուրս հանեց, նաև ոչխարներն ու արջառները, իսկ լումայափոխների դրամները ցրիվ տվեց և սեղանները շուռ տվեց։","16":"Նա աղավնեվաճառներին ասաց. «Դրանք այստեղից վերցրե՛ք և իմ Հոր տունը վաճառատուն մի՛ դարձրեք»։","17":"Եվ նրա աշակերտները հիշեցին, որ գրված է. «Քո տան նկատմամբ նախանձախնդրությունն ինձ պիտի ուտի» (Սաղ. 69.9ա)։","18":"Հրեաները նրան հարցրին. «Ի՞նչ նշան կարող ես մեզ ցույց տալ, որ իրավունք ունես այդ անելու»։","19":"Հիսուսը նրանց պատասխանեց և ասաց. «Քանդե՛ք այս տաճարը, և երեք օրում ես կվերականգնեմ այն»։","20":"Հրեաներն ասացին. «Այս տաճարը քառասունվեց տարում է կառուցվել, իսկ դու երեք օրո՞ւմ այն կվերականգնես»։","21":"Բայց նա իր մարմնի տաճարի մասին էր խոսում։","22":"Իսկ երբ նա մեռելներից հարություն առավ, նրա աշակերտները հիշեցին, որ սրա մասին էր խոսում, և հավատացին Սուրբ Գրքին և Հիսուսի ասած խոսքին։","23":"Երբ Հիսուսը Զատկի տոնին Երուսաղեմում էր, շատ մարդիկ հավատացին նրա անվանը՝ տեսնելով նրա գործած հրաշքները։","24":"Բայց Հիսուսը նրանց չէր վստահում, որովհետև ինքը բոլորին ճանաչում էր։","25":"Եվ կարիք չկար, որ մեկը մարդու մասին վկայեր, որովհետև ինքը գիտեր՝ ի՛նչ կար մարդու մեջ։"},"3":{"1":"Փարիսեցիներից մի մարդ կար՝ Նիկոդեմոս անունով, որ հրեաների իշխանավոր էր։","2":"Նա գիշերը Հիսուսի մոտ եկավ ու ասաց նրան. «Ռա՛բբի, գիտենք, որ Աստծուց ես եկել իբրև վարդապետ, որովհետև ոչ ոք չի կարող գործել այն հրաշքները, որ դու ես գործում, եթե Աստված նրա հետ չլինի»։","3":"Հիսուսը նրան ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում քեզ. եթե մեկը վերստին չծնվի, Աստծու արքայությունը չի կարող տեսնել»։","4":"Նիկոդեմոսը նրան ասաց. «Ինչպե՞ս կարող է ծնվել մի մարդ, որ ծեր է. մի՞թե կարող է երկրորդ անգամ իր մոր որովայնը մտնել ու ծնվել»։","5":"Հիսուսը պատասխանեց. «Ճշմարիտ, ճշմարիտ եմ ասում քեզ. եթե մեկը ջրից ու Հոգուց չծնվի, նա չի կարող մտնել Աստծու արքայությունը։","6":"Մարմնից ծնվածը մարմին է, իսկ Հոգուց ծնվածը՝ հոգի։","7":"Մի՛ զարմացիր, որ քեզ ասացի. \"Դուք պետք է վերստին ծնվեք\"։","8":"Քամին ուր ուզում է, փչում է, և նրա ձայնը լսում ես, բայց չգիտես, թե որտեղի՛ց է գալիս և ո՛ւր է գնում. այդպես է և Հոգուց ծնված ամեն ոք»։","9":"Նիկոդեմոսը հարցրեց ու նրան ասաց. «Դա ինչպե՞ս կարող է լինել»։","10":"Հիսուսը պատասխանեց նրան. «Դու Իսրայելի վարդապետն ես ու դա չգիտե՞ս։","11":"Ճշմարիտ, ճշմարիտ եմ ասում քեզ. ասում ենք այն, ինչ գիտենք, վկայում ենք, ինչ տեսել ենք, բայց մեր վկայությունը չեք ընդունում։","12":"Եթե ձեզ երկրային բաներն ասացի, ու ինձ չեք հավատում, հապա ինչպե՞ս պիտի հավատաք, եթե երկնային բաներն ասեմ։","13":"Ոչ ոք երկինք չի բարձրացել, բացի Մարդու Որդուց, որ իջավ երկնքից և որ երկնքում է։","14":"Եվ ինչպես Մովսեսն անապատում օձին բարձրացրեց, այնպես էլ Մարդու Որդին պետք է բարձրանա,","15":"որպեսզի ով նրան հավատում է, հավիտենական կյանք ունենա։","16":"Աստված այնքան սիրեց աշխարհը, որ իր միածին Որդուն տվեց, որպեսզի ով նրան հավատում է, չկորչի, այլ հավիտենական կյանք ունենա։","17":"Որովհետև Աստված իր Որդուն աշխարհ չուղարկեց՝ դատելու աշխարհը, այլ որպեսզի նրա միջոցով աշխարհը փրկվի։","18":"Ով նրան հավատում է, չպիտի դատապարտվի, իսկ ով նրան չի հավատում, արդեն դատապարտված է, որովհետև չհավատաց Աստծու միածին Որդու անվանը։","19":"Եվ ահա այս է դատաստանը. լույսը եկավ աշխարհ, սակայն մարդիկ խավարը լույսից ավելի սիրեցին, որովհետև իրենց գործերը չար էին։","20":"Որովհետև յուրաքանչյուր ոք, ով չարիք է գործում, ատում է լույսը ու չի գալիս դեպի լույսը, որպեսզի իր գործերը հայտնի չդառնան։","21":"Իսկ ով կատարում է այն, ինչ ճշմարիտ է, գալիս է դեպի լույսը, որպեսզի հայտնի դառնա, թե իր գործերը Աստծով են կատարվել»։","22":"Դրանից հետո Հիսուսը և իր աշակերտները եկան Հուդայի երկիր։ Նա նրանց հետ այնտեղ մնաց և մկրտում էր։","23":"Իսկ Հովհաննեսը Այենոնում՝ Սաղեմի մոտ էր մկրտում, որովհետև այնտեղ շատ ջուր կար. մարդիկ գալիս էին ու մկրտվում,","24":"քանի որ Հովհաննեսը դեռ չէր բանտարկվել։","25":"Եվ ահա Հովհաննեսի աշակերտների և մի հրեայի միջև մաքրության մասին վեճ ծագեց։","26":"Եկան Հովհաննեսի մոտ ու նրան ասացին. «Ռա՛բբի, նա, որ քեզ հետ Հորդանանի մյուս կողմում էր, որի մասին դու վկայեցիր, ահա նա մկրտում է, և ամենքը նրա մոտ են գալիս»։","27":"Հովհաննեսն ասաց. «Մարդ ոչինչ չի կարող ընդունել, եթե նրան երկնքից տրված չլինի։","28":"Դուք ինքներդ վկա եք իմ ասածներին. \"Ես Քրիստոսը չեմ, այլ նրանից առաջ եմ ուղարկվել\"։","29":"Ով հարս ունի, նա է փեսան, բայց փեսայի բարեկամը, որ մոտ է կանգնած ու լսում է նրան, ուրախությամբ է լցվում, երբ լսում է փեսայի ձայնը. արդ այս է իմ ուրախությունը, և այժմ այն կատարյալ է։","30":"Նրա գործը պետք է մեծանա, իսկ իմը՝ փոքրանա։","31":"Նա, որ գալիս է ի վերուստ, ամենքից վեր է. իսկ երկրից ելնողը երկրավոր է ու երկրային բաներից է խոսում. երկնքից եկողն ամենքից վեր է։","32":"Նա վկայում է այն, ինչ տեսել ու լսել է, սակայն նրա վկայությունը ոչ ոք չի ընդունում։","33":"Նրա վկայությունն ընդունողը հաստատում է, որ Աստված ճշմարիտ է։","34":"Որովհետև նա, ում Աստված ուղարկեց, Աստծու խոսքն է խոսում, որովհետև Աստված Հոգին ըստ չափի չի տալիս։","35":"Հայրը սիրում է Որդուն և ամեն բան նրա ձեռքն է տվել։","36":"Որդուն հավատացողը հավիտենական կյանք ունի, իսկ Որդուն չհնազանդվողը կյանք չի տեսնի, այլ Աստծու բարկությունը կմնա նրա վրա»։"},"4":{"1":"Երբ Հիսուսն իմացավ, որ փարիսեցիները լսել են, թե ինքն ավելի շատ աշակերտներ է ձեռք բերում և մկրտում, քան Հովհաննեսը","2":"(թեև Հիսուսն ինքը չէր մկրտում, այլ նրա աշակերտները),","3":"թողեց Հուդայի երկիրն ու կրկին Գալիլեա եկավ։","4":"Եվ պետք է Սամարիայի միջով անցներ։","5":"Արդ նա Սամարիայի մի քաղաք եկավ, որ Սյուքար էր կոչվում, մոտիկ այն ագարակին, որ Հակոբը տվել էր իր որդի Հովսեփին։","6":"Այնտեղ էր գտնվում Հակոբի աղբյուրը։ Հիսուսը, ճանապարհից հոգնած, նստեց այդ աղբյուրի մոտ։ Վեցերորդ ժամն էր։","7":"Սամարացի մի կին եկավ ջուր հանելու։ Հիսուսը նրան ասաց. «Ինձ ջո՛ւր տուր՝ խմեմ».","8":"քանի որ նրա աշակերտները քաղաք էին գնացել ուտելիք գնելու։","9":"Սամարացի կինը նրան ասաց. «Դու, որ հրեա ես, ինչպե՞ս ես ինձանից՝ սամարացի կնոջից, խմելու ջուր ուզում». որովհետև հրեաները սամարացիների հետ չէին շփվում։","10":"Հիսուսը պատասխանեց նրան ու ասաց. «Եթե իմանայիր Աստծու պարգևը, և թե ո՛վ է նա, որ քեզ ասում է՝ \"Ինձ խմելու ջո՛ւր տուր\", ապա դո՛ւ նրանից կխնդրեիր, նա էլ քեզ կենդանի ջուր կտար»։","11":"Կինը նրան ասաց. «Տե՛ր, դու նույնիսկ դույլ չունես, իսկ ջրհորը խորն է. արդ կենդանի ջուրը որտեղի՞ց ունես։","12":"Մի՞թե դու ավելի մեծ ես, քան մեր հայր Հակոբը, որ այս ջրհորը մեզ տվեց. ինքը, իր որդիներն ու հոտերը խմել են սրանից»։","13":"Հիսուսը պատասխանեց նրան ու ասաց. «Ով այդ ջրից խմի, կրկին կծարավի, բայց ով խմի այն ջրից, որ ես եմ տալու նրան, նա հավիտյան չպիտի ծարավի։","14":"Իսկ այն ջուրը, որ ես նրան տալու եմ, նրա մեջ ջրի աղբյուր կդառնա, որ հավիտենական կյանքի համար կբխի»։","15":"Կինը նրան ասաց. «Տե՛ր, տո՛ւր ինձ այդ ջրից, որ չծարավեմ և չգամ այստեղ ջուր հանելու»։","16":"Հիսուսը նրան ասաց. «Գնա ամուսնուդ կանչի՛ր ու այստե՛ղ արի»։","17":"Կինը պատասխանեց. «Ես ամուսին չունեմ»։ Հիսուսը նրան ասաց. «Լավ ասացիր՝ \"Ամուսին չունեմ\",","18":"որովհետև դու հինգ ամուսին ես ունեցել, և նա, ում հիմա ունես, քո ամուսինը չէ. դա ճիշտ ասացիր»։","19":"Կինը նրան ասաց. «Տե՛ր, տեսնում եմ, որ դու մարգարե ես։","20":"Մեր հայրերն այս լեռան վրա երկրպագություն են արել, իսկ դուք ասում եք, թե Երուսաղեմում է այն տեղը, որտեղ պետք է երկրպագություն անել»։","21":"Հիսուսը նրան ասաց. «Կի՛ն, հավատա՛ ինձ, որ ժամանակը կգա, երբ ո՛չ այս լեռան վրա, ո՛չ էլ Երուսաղեմում կերկրպագեք Հորը։","22":"Դուք երկրպագում եք նրան, ում չգիտեք. մենք երկրպագում ենք նրան, ում գիտենք. որովհետև փրկությունը հրեաներից է։","23":"Բայց ժամանակը կգա, և արդեն եկել է, երբ ճշմարիտ երկրպագողները կերկրպագեն Հորը հոգով ու ճշմարտությամբ, որովհետև Հայրն իրեն այդպիսի երկրպագողներ է ուզում։","24":"Աստված Հոգի է, ու նրան երկրպագողները պետք է հոգով ու ճշմարտությամբ երկրպագեն»։","25":"Կինը նրան ասաց. «Գիտեմ, որ գալու է Մեսիան (որ Քրիստոս է կոչվում). երբ նա գա, մեզ ամեն ինչ կպատմի»։","26":"Հիսուսը նրան ասաց. «Ես եմ՝ քեզ հետ խոսողը»։","27":"Եվ այդժամ եկան նրա աշակերտները ու զարմանում էին, որ նա կնոջ հետ էր խոսում, բայց ոչ ոք չասաց՝ «Ի՞նչ ես ուզում» կամ «Դրա հետ ի՞նչ ես խոսում»։","28":"Կինը թողեց իր կուժը, գնաց քաղաք ու մարդկանց ասաց.","29":"«Եկեք տեսե՛ք մի մարդու, որն ինձ ասաց այն ամենը, ինչ արել եմ. արդյոք նա՞ է Քրիստոսը»։","30":"Եվ ելան քաղաքից ու նրա մոտ էին գալիս։","31":"Այդ ընթացքում աշակերտները նրան խնդրում էին ու ասում. «Ռա՛բբի, հա՛ց կեր»։","32":"Իսկ նա նրանց ասաց. «Ես ուտելու կերակուր ունեմ, որ դուք չգիտեք»։","33":"Աշակերտներն իրար մեջ ասում էին. «Գուցե մեկը նրան ուտելի՞ք է բերել»։","34":"Հիսուսը նրանց ասաց. «Իմ կերակուրն այն է, որ ինձ ուղարկողի կամքը կատարեմ և նրա գործը ավարտին հասցնեմ։","35":"Արդյոք դո՞ւք չեք ասում. \"Չորս ամիս ևս, և հունձը կհասնի\"։ Ահա ես ասում եմ ձեզ. բարձրացրե՛ք ձեր աչքերը ու տեսե՛ք արտերը, որ սպիտակել են ու արդեն հասել հնձի համար։","36":"Հնձողը վարձ է ստանում և հավիտենական կյանքի համար պտուղ հավաքում, որպեսզի ուրախանան և՛ սերմանողը, և՛ հնձողը։","37":"Որովհետև սրանով է ճշմարիտ այն խոսքը, թե՝ \"Այլ է սերմանողը, և այլ՝ հնձողը\"։","38":"Ես ձեզ ուղարկեցի հնձելու այն, ինչ դուք չեք մշակել. ուրիշներն աշխատեցին, իսկ դուք նրանց վաստակի մեջ մտաք»։","39":"Եվ այն քաղաքի սամարացիներից շատերը հավատացին նրան այն կնոջ խոսքի համար, որ վկայեց, թե՝ «Ինձ ասաց այն ամենը, ինչ ես արել էի»։","40":"Արդ երբ սամարացիները նրա մոտ եկան, խնդրեցին նրան, որ իրենց հետ մնա, և նա երկու օր այնտեղ մնաց։","41":"Եվ ուրիշ շատերն էլ նրա խոսքի համար հավատացին նրան։","42":"Եվ կնոջն ասում էին. «Այլևս ոչ թե քո խոսքերի՛ համար ենք նրան հավատում, այլ որ մենք ինքներս լսեցինք ու գիտենք, որ ճշմարտապես նա է աշխարհի Փրկիչը»։","43":"Եվ երկու օր հետո նա ելավ այնտեղից և գնաց Գալիլեա,","44":"թեև Հիսուսն ինքը վկայել էր. «Մարգարեն իր հայրենիքում պատիվ չունի»։","45":"Բայց երբ Գալիլեա եկավ, գալիլեացիները նրան ընդունեցին, որովհետև նրանք տեսել էին այն ամենը, ինչ արել էր Զատկի տոնին Երուսաղեմում, քանի որ նրանք էլ էին եկել տոնին։","46":"Եվ Հիսուսը դարձյալ եկավ Գալիլեայի Կանա քաղաքը, որտեղ ջուրը գինու էր վերածել։ Թագավորի պաշտոնյաներից մի մարդ կար, որի որդին Կափառնաումում հիվանդ էր։","47":"Նա, լսելով, որ Հիսուսը Հուդայից Գալիլեա է եկել, եկավ նրա մոտ և խնդրում էր, որ Կափառնաում իջնի ու իր որդուն բժշկի, որովհետև մահամերձ էր։","48":"Հիսուսը նրան ասաց. «Եթե նշաններ ու հրաշքներ չտեսնեք, չեք հավատա»։","49":"Պաշտոնյան նրան ասաց. «Տե՛ր, իջի՛ր, քանի դեռ որդիս չի մեռել»։","50":"Հիսուսը նրան ասաց. «Գնա՛, քո որդին կենդանի է»։ Եվ մարդը հավատաց Հիսուսի ասած խոսքին ու գնաց։","51":"Եվ մինչ նա իջնում էր, նրա ծառաներն ընդառաջ ելան նրան, ավետիս տվեցին ու ասացին. «Քո որդին կենդանի է»։","52":"Իսկ նա հարցրեց նրանց, թե ո՛ր ժամին սկսեց ապաքինվել։ Եվ նրան ասացին. «Երեկ յոթերորդ ժամին տենդը նրան թողեց»։","53":"Այդժամ հայրը հասկացավ, որ դա նույն ժամն էր, երբ Հիսուսն իրեն ասաց. «Քո որդին կենդանի է»։ Եվ հավատացին ինքը և իր ամբողջ ընտանիքը։","54":"Սա երկրորդ հրաշքն էր, որ Հիսուսը գործեց, երբ Հուդայից եկավ Գալիլեա։"},"5":{"1":"Դրանից հետո հրեաների տոնն էր, և Հիսուսը Երուսաղեմ բարձրացավ։","2":"Երուսաղեմում՝ Ոչխարաց դռան մոտ, մի ավազան կա, որ եբրայերեն Բեթհեզդա է կոչվում, որը հինգ սրահ ունի։","3":"Դրանց մեջ պառկած էին շատ հիվանդներ՝ կույրեր, կաղեր, գոսացածներ [որոնք ջրերի խառնվելուն էին սպասում,","4":"որովհետև Տիրոջ հրեշտակը ժամանակ առ ժամանակ իջնում էր ավազանի մեջ և ջրերը խառնում. ջրերի խառնվելուց հետո ով առաջինը դրա մեջ մտներ, բժշկվում էր, ինչ հիվանդությունից էլ որ տառապեր]։","5":"Այնտեղ մի մարդ կար, որ երեսունութ տարի հիվանդ էր։","6":"Երբ Հիսուսը նրան տեսավ պառկած և իմացավ, որ արդեն երկար ժամանակ է, նրան ասաց. «Ուզո՞ւմ ես առողջանալ»։","7":"Հիվանդը նրան պատասխանեց. «Տե՛ր, ոչ ոք չունեմ, որ ջրերի խառնվելու ժամանակ ինձ ավազանի մեջ իջեցնի. մինչ ես գալիս եմ, ուրիշն ինձանից առաջ իջնում է»։","8":"Հիսուսը նրան ասաց. «Վե՛ր կաց, վերցրո՛ւ մահիճդ և քայլի՛ր»։","9":"Եվ մարդն իսկույն առողջացավ, վերցրեց իր մահիճը ու քայլում էր։ Եվ այդ օրը շաբաթ էր։","10":"Հրեաները բժշկվածին ասացին. «Օրը շաբաթ է. քեզ օրինավոր չէ, որ մահիճդ վերցնես»։","11":"Սակայն նա պատասխանեց նրանց. «Նա, ով ինձ բժշկեց, ինձ ասաց. \"Վերցրո՛ւ մահիճդ ու քայլի՛ր\"»։","12":"Նրան հարցրին. «Ո՞վ է այն մարդը, որ քեզ ասաց՝ \"Վերցրո՛ւ մահիճդ ու քայլի՛ր\"»։","13":"Սակայն բժշկվածը չգիտեր, թե նա ո՛վ էր, որովհետև Հիսուսն ամբոխի պատճառով հեռացել էր այնտեղից։","14":"Դրանից հետո Հիսուսը նրան գտավ տաճարում ու ասաց. «Տե՛ս, առողջացար. այսուհետ մի՛ մեղանչիր, որպեսզի քեզ է՛լ ավելի չար բան չպատահի»։","15":"Մարդը գնաց ու հրեաներին պատմեց, որ իրեն բժշկողը Հիսուսն էր։","16":"Եվ դրա համար էին հրեաները Հիսուսին հալածում, որ դա շաբաթ օրով էր անում։","17":"Եվ Հիսուսը նրանց պատասխանեց. «Իմ Հայրը մինչև հիմա գործում է, արդ ես նույնպես գործում եմ»։","18":"Դրա համար հրեաներն է՛լ ավելի էին ուզում նրան սպանել, որովհետև ոչ միայն շաբաթ օրվա կանոնն էր խախտում, այլև Աստծուն էլ իրեն Հայր էր կոչում և իր անձն Աստծուն հավասար էր դասում։","19":"Այդժամ Հիսուսը նրանց ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. Որդին ինքն իրենից ոչինչ անել չի կարող, եթե չտեսնի այն, ինչ Հայրն է անում, որովհետև ինչ որ նա է անում, Որդին էլ է նույնը գործում։","20":"Որովհետև Հայրը սիրում է Որդուն և ցույց է տալիս նրան այն ամենը, ինչ ինքն է անում, և նրան է՛լ ավելի մեծ գործեր է ցույց տալու, որ դուք պիտի զարմանաք։","21":"Որովհետև ինչպես Հայրն է մեռելներին հարություն տալիս և կենդանացնում, այնպես էլ Որդին ում կամենում է, կենդանացնում է։","22":"Հայրը ոչ ոքի չի դատում, այլ դատելու ողջ իշխանությունը Որդուն է տվել,","23":"որպեսզի բոլորը Որդուն պատվեն, ինչպես Հորն են պատվում. ով Որդուն չի պատվում, չի պատվում նաև Հորը, որ ուղարկել է նրան։","24":"Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. ով լսում է իմ խոսքը և հավատում է ինձ ուղարկողին, հավիտենական կյանք ունի և չի դատապարտվի, այլ մահից դեպի կյանք է անցել։","25":"Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, որ ժամանակը կգա, և արդեն իսկ եկել է, երբ մեռելները կլսեն Աստծու Որդու ձայնը, ու ովքեր լսեն, կապրեն։","26":"Որովհետև ինչպես Հայրն է կյանքի աղբյուր, այնպես էլ Որդուն դարձրեց կյանքի աղբյուր։","27":"Եվ նրան իշխանություն տվեց մարդկանց դատելու, որովհետև նա Մարդու Որդին է։","28":"Մի՛ զարմացեք, որովհետև կգա ժամանակ, երբ բոլոր նրանք, որ գերեզմաններում են, կլսեն նրա ձայնը։","29":"Ովքեր բարիք են գործել, հարություն կառնեն կյանքի համար, իսկ նրանք, որ չարիք են գործել, հարություն կառնեն դատաստանի համար։","30":"Ես ինքս ինձանից ոչինչ չեմ կարող անել. ինչպես լսում եմ, այնպես էլ դատում եմ, և իմ դատաստանն արդար է, որովհետև ես իմ կամքը չեմկատարում, այլ ինձ ուղարկողի կամքը։","31":"Եթե ես իմ մասին վկայեմ, իմ վկայությունը հավաստի չի լինի։","32":"Ուրիշն է, որ վկայում է իմ մասին, ու ես գիտեմ, որ այն, ինչ նա վկայում է իմ մասին, հավաստի է։","33":"Դուք Հովհաննեսի մոտ մարդ ուղարկեցիք, և նա վկայեց ճշմարտությունը։","34":"Իսկ ես կարիք չունեմ մարդկանցից վկայություն առնելու, այլ սա ասում եմ, որ դուք փրկվեք։","35":"Հովհաննեսը այն վառվող ճրագն էր, որ լույս էր տալիս, և դուք ցանկացաք միառժամանակ նրա լույսով ուրախանալ։","36":"Սակայն այն վկայությունը, որ ես ունեմ իմ մասին, ավելի մեծ է, քան Հովհաննեսինը, որովհետև այն գործերը, որ Հայրն է ինձ տվել իրագործելու, այդ նույն գործերը վկայում են իմ մասին, որ Հայրն է ինձ ուղարկել։","37":"Եվ Հայրը, որ ինձ ուղարկեց, ինքն է իմ մասին վկայել, սակայն դուք ո՛չ նրա ձայնը երբևէ լսեցիք, ո՛չ նրա կերպարանքը տեսաք։","38":"Ոչ էլ նրա խոսքն ունեք ձեր մեջ, որովհետև նրան, ում որ նա ուղարկեց, դուք չեք հավատում։","39":"Դուք քննում եք Սուրբ Գիրքը՝ կարծելով, թե դրա մեջ եք գտնելու հավիտենական կյանքը։ Սակայն դա էլ վկայում է իմ մասին։","40":"Բայց դուք չեք կամենում ինձ մոտ գալ, որպեսզի կյանք ունենաք։","41":"Ես մարդկանցից փառք չեմ ուզում։","42":"Բայց ձեզ ճանաչում եմ, գիտեմ, որ ձեր մեջ Աստծու սերը չունեք։","43":"Ես իմ Հոր անունով եկա, և ինձ չեք ընդունում։ Եթե ուրիշ մեկը գա իր անունով, նրան կընդունեք։","44":"Դուք ինչպե՞ս կարող եք հավատալ, երբ իրարից փառք եք ընդունում և այն փառքը, որ միայն Աստծուց է, չեք փնտրում։","45":"Մի՛ կարծեք, թե ես Հոր առաջ ձեզ պիտի ամբաստանեմ։ Ձեզ ամբաստանող կա, և դա Մովսեսն է, որի վրա դուք հույս եք դրել։","46":"Որովհետև եթե դուք Մովսեսին հավատայիք, ինձ էլ կհավատայիք, քանի որ նա իմ մասին է գրել։","47":"Բայց եթե նրա գրածներին չեք հավատում, իմ խոսքերին ինչպե՞ս պիտի հավատաք»։"},"6":{"1":"Դրանից հետո Հիսուսը գնաց Գալիլեայի՝ Տիբերիա լճի մյուս կողմը։","2":"Նրա հետևից մեծ բազմություն էր գնում, որովհետև տեսնում էին նրա հրաշքները, որ կատարում էր հիվանդների վրա։","3":"Հիսուսը լեռը բարձրացավ և իր աշակերտների հետ նստեց այնտեղ։","4":"Մոտենում էր Զատիկը՝ հրեաների տոնը։","5":"Հիսուսն աչքերը վեր բարձրացրեց ու տեսավ, որ բազում ժողովուրդ է գալիս իր մոտ։ Նա Փիլիպպոսին ասաց. «Որտեղի՞ց պիտի հաց գնենք, որ նրանք ուտեն»։","6":"Բայց Հիսուսը սա նրան փորձելու համար ասաց, որովհետև ինքը գիտեր, թե ի՛նչ է անելու։","7":"Փիլիպպոսը նրան պատասխանեց. «Նույնիսկ երկու հարյուր դինարի հացը նրանց չի բավականացնի, թեկուզ նրանցից յուրաքանչյուրը մի կտոր վերցնի»։","8":"Նրա աշակերտներից մեկը՝ Անդրեասը՝ Սիմոն Պետրոսի եղբայրը, նրան ասաց.","9":"«Այստեղ մի պատանի կա, որ հինգ գարեհաց ունի և երկու ձուկ, բայց դա ի՞նչ է այսքան մարդու համար»։","10":"Հիսուսն էլ ասաց. «Մարդկանց գետնի՛ն նստեցրեք»։ Այնտեղ շատ խոտ կար։ Արդ նստեցին. շուրջ հինգ հազար մարդ կար։","11":"Հիսուսը հացը վերցրեց, գոհություն հայտնեց Աստծուն ու բաշխեց նստածներին. նույն կերպ էլ ձկներից բաշխեց, որքան որ կամեցան։","12":"Երբ կշտացան, իր աշակերտներին ասաց. «Ավելացած կտորները հավաքե՛ք, որպեսզի ոչինչ չկորչի»։","13":"Հավաքեցին և ուտողներից ավելացած այն հինգ գարեհացի կտորներից տասներկու կողով լցրեցին։","14":"Երբ մարդիկ տեսան այդ հրաշքը, որ Հիսուսը գործեց, ասացին. «Ճշմարտապես սա է այն մարգարեն, որ աշխարհ էր գալու»։","15":"Սակայն քանի որ Հիսուսը գիտեր, որ գալու են իրեն բռնելու, որպեսզի թագավոր դարձնեն, դարձյալ միայնակ լեռը գնաց։","16":"Երբ երեկո եղավ, նրա աշակերտները լճափ իջան","17":"և նավ նստելով՝ գնացին լճի մյուս կողմը՝ Կափառնաում։ Արդեն մթնել էր, և Հիսուսը դեռ նրանց մոտ չէր եկել։","18":"Սաստիկ քամու փչելուց լիճն ալեկոծվում էր։","19":"Քսանհինգ կամ երեսուն ասպարեզի չափ թիավարելուց հետո տեսան Հիսուսին, որ քայլում էր լճի վրայով և նավին էր մոտենում։ Եվ նրանք սաստիկ վախեցան։","20":"Հիսուսն ասաց նրանց. «Ես եմ, մի՛ վախեցեք»։","21":"Նրանք կամեցան Հիսուսին նավ հանել, սակայն նավը շուտով ցամաք հասավ, ուր որ ուղևորվում էին։","22":"Հաջորդ օրը ժողովուրդը, որ մնացել էր լճի մյուս կողմում, տեսավ, որ այնտեղ ուրիշ նավ չկար, բացի այն մեկից, որի մեջ նրա աշակերտներն էին նստել, իսկ Հիսուսն իր աշակերտների հետ նավ չէր նստել, այլ միայն նրա աշակերտներն էին գնացել։","23":"Բայց Տիբերիայից ուրիշ նավեր էլ էին գալիս այն տեղին մոտ, որտեղ Տիրոջ գոհության աղոթքով հացն էին կերել։","24":"Արդ երբ ժողովուրդը տեսավ, որ ո՛չ Հիսուսն է այնտեղ, ո՛չ էլ նրա աշակերտները, իրենք էլ նավեր նստեցին և եկան Կափառնաում՝ Հիսուսին փնտրելու։","25":"Եվ երբ նրան գտան լճի մյուս կողմում, ասացին. «Ռա՛բբի, ե՞րբ այստեղ եկար»։","26":"Հիսուսը նրանց պատասխանեց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. դուք ինձ փնտրում եք ոչ թե նրա համար, որ հրաշքներ տեսաք, այլ որովհետև այն հացից կերաք ու կշտացաք։","27":"Աշխատե՛ք ոչ թե կորստյան ենթակա կերակուրի համար, այլ այն կերակուրի, որ մնում է հավիտենական կյանքում։ Այդ կերակուրը ձեզ կտա Մարդու Որդին, որովհետև Հայրը՝ Աստված, նրան այդ գործն անելու իշխանություն է շնորհել»։","28":"Արդ նրան ասացին. «Ի՞նչ անենք, որ Աստծու գործերը կատարենք»։","29":"Հիսուսը պատասխանեց նրանց. «Աստծու գործն այն է, որ հավատաք նրան, ում նա ուղարկել է»։","30":"Եվ նրան ասացին. «Դու ի՞նչ նշան կանես, որ տեսնենք ու քեզ հավատանք, ի՞նչ կգործես։","31":"Մեր հայրերն անապատում մանանան կերան, ինչպես որ գրված է. \"Երկնքից նրանց ուտելու հաց տվեց\" (Սաղ. 78.24)»։","32":"Հիսուսը նրանց ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. երկնքից այն հացը ձեզ Մովսեսը չի տվել, այլ իմ Հայրն է ձեզ ճշմարիտ հացը տալիս երկնքից,","33":"որովհետև Աստծու հացն այն է, որ երկնքից է իջնում և կյանք է տալիս աշխարհին»։","34":"Նրանք ասացին Հիսուսին. «Տե՛ր, ամեն ժամ տո՛ւր մեզ այդ հացը»։","35":"Հիսուսը նրանց ասաց. «Ես եմ կյանքի հացը. դեպի ինձ եկողը չի քաղցի, և ինձ հավատացողը երբեք չի ծարավի։","36":"Բայց ես ասացի ձեզ, որ թեև ինձ տեսաք, սակայն չեք հավատում։","37":"Նա, ում Հայրը ինձ տալիս է, կգա ինձ մոտ, և ինձ մոտ եկողին ես դուրս չեմ անի,","38":"որովհետև ես իջել եմ երկնքից, որպեսզի ոչ թե իմ կամքը կատարեմ, այլ ինձ ուղարկողի կամքը։","39":"Ինձ ուղարկողի կամքն այն է, որ նրանցից ոչ մեկին, որոնց նա ինձ տվել է, չկորցնեմ, այլ վերջին օրը հարություն տամ նրանց։","40":"Այս է իմ Հոր կամքը. ով Որդուն տեսնի ու հավատա նրան, հավիտենական կյանք կունենա, ու ես վերջին օրը հարություն կտամ նրան»։","41":"Այդժամ հրեաները վրդովվում էին, որ ասաց. «Ես եմ երկնքից իջած հացը»։","42":"Եվ ասում էին. «Սա Հիսուսը չէ՞, Հովսեփի որդին, որի հորն ու մորը ճանաչում ենք։ Հիմա ինչպե՞ս է ասում՝ \"Ես երկնքից եմ իջել\"»։","43":"Հիսուսը պատասխանեց նրանց. «Իրար մեջ մի՛ քրթմնջացեք։","44":"Ոչ ոք չի կարող ինձ մոտ գալ, եթե նրան դեպի ինձ չբերի Հայրը, որն ինձ ուղարկեց, և ես վերջին օրը հարություն կտամ նրան։","45":"Մարգարեների գրքերում գրված է. \"Աստված ինքը բոլորին կուսուցանի\" (Ես. 54.13ա)։ Արդ, ով Հորից լսում ու սովորում է, ինձ մոտ է գալիս։","46":"Բայց ոչ ոք չի տեսել Հորը. միայն նա, ով Աստծուց է, նա՛ է տեսել Հորը։","47":"Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. ինձ հավատացողը հավիտենական կյանք ունի։","48":"Ես եմ կյանքի հացը։","49":"Ձեր հայրերն անապատում կերան մանանան, բայց մեռան։","50":"Սակայն ով ուտի այն հացից, որ երկնքից է իջել, չի մեռնի։","51":"Ես եմ կենդանի հացը, որ երկնքից է իջել։ Եթե մեկն այս հացից ուտի, հավիտյան կապրի, և այն հացը, որ ես կտամ, իմ մարմինն է, որ ես տալու եմ աշխարհի կյանքի համար»։","52":"Այդժամ հրեաները միմյանց հետ վիճաբանում էին ու ասում. «Սա ինչպե՞ս կարող է իր մարմինը մեզ տալ՝ ուտելու»։","53":"Հիսուսը նրանց ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. եթե Մարդու Որդու մարմինը չուտեք և նրա արյունը չխմեք, ձեր մեջ կյանք չեք ունենա։","54":"Ով ուտում է իմ մարմինը և խմում իմ արյունը, հավիտենական կյանք ունի, և ես վերջին օրը նրան հարություն կտամ։","55":"Որովհետև իմ մարմինը ճշմարիտ կերակուր է, և իմ արյունը ճշմարիտ ըմպելիք է։","56":"Ով ուտում է իմ մարմինը և խմում իմ արյունը, ինձ հետ է միավորվում, ես էլ՝ նրա հետ։","57":"Ինչպես կենդանի Հայրը ինձ ուղարկեց, և ես ապրում եմ Հոր միջոցով, այնպես էլ նա, ով ինձ ուտում է, կապրի ինձանով։","58":"Սա է այն հացը, որ երկնքից է իջել, և ո՛չ մանանան, որ ձեր հայրերը կերան, բայց մեռան։ Նա, ով ուտի այս հացը, հավիտյան կապրի»։","59":"Հիսուսն այս ասաց ժողովարանում, երբ Կափառնաումում ուսուցանում էր։","60":"Եվ նրա աշակերտներից շատերը երբ լսեցին, ասացին. «Խիստ է այդ խոսքը. ո՞վ կարող է դա լսել»։","61":"Բայց երբ Հիսուսն ինքն իր մեջ իմացավ, որ իր աշակերտները դրա համար տրտնջում են, նրանց ասաց. «Դա ձեզ գայթակղեցնո՞ւմ է։","62":"Իսկ եթե տեսնեք Մարդու Որդուն վեր բարձրանալիս այնտեղ, որտեղ առա՞ջ էր։","63":"Հոգին է կյանք տվողը. մարմինը ոչ մի օգուտ չի տալիս։ Այն խոսքը, որ ես ձեզ ասացի, հոգի է ու կյանք։","64":"Բայց ձեր մեջ կան ոմանք, որ չեն հավատում»։ Որովհետև Հիսուսը սկզբից գիտեր, թե ովքեր էին նրանք, որ չեն հավատում, և ով էր նա, որ մատնելու էր իրեն։","65":"Եվ ասաց. «Դրա համար ձեզ ասացի, որ ոչ ոք չի կարող գալ ինձ մոտ, եթե իմ Հոր կողմից տրված չէ նրան»։","66":"Դրանից հետո նրա աշակերտներից շատերը հետ քաշվեցին ու նրան այլևս չհետևեցին։","67":"Արդ Հիսուսն այն տասներկուսին ասաց. «Գուցե դուք է՞լ եք ուզում գնալ»։","68":"Սիմոն Պետրոսը պատասխանեց նրան. «Տե՛ր, ո՞ւմ մոտ գնանք. դու հավիտենական կյանքի խոսքեր ունես։","69":"Եվ մենք հավատացինք ու ճանաչեցինք, որ դու ես Քրիստոսը՝ կենդանի Աստծու Որդին»։","70":"Հիսուսը նրանց պատասխանեց. «Չէ՞ որ ես եմ ընտրել ձեզ՝ տասներկուսիդ, սակայն ձեզանից մեկը սատանա է»։","71":"Եվ նա Սիմոնի որդի Հուդա Իսկարիովտացու մասին էր ասում, որովհետև նա էր տասներկուսից մեկը, որ մատնելու էր նրան։"},"7":{"1":"Դրանից հետո Հիսուսը շրջում էր Գալիլեայում։ Նա չէր ուզում շրջել Հուդայում, քանի որ հրեաներն ուզում էին սպանել նրան։","2":"Մոտենում էր հրեաների Տաղավարահարաց տոնը։","3":"Հիսուսի եղբայրները նրան ասացին. «Դո՛ւրս արի այստեղից և գնա՛ Հուդա, որ քո աշակերտներն էլ տեսնեն այն գործերը, որ անում ես։","4":"Որովհետև չկա մեկը, որ գաղտնի գործի և ուզենա հայտնի լինել. եթե այդ գործերն անում ես, ուրեմն հայտնի՛ր քեզ աշխարհին»։","5":"Հիսուսի եղբայրները նույնպես չէին հավատում նրան։","6":"Հիսուսը նրանց ասաց. «Իմ ժամանակը դեռ չի հասել, բայց ձեզ համար միշտ ժամանակն է։","7":"Աշխարհը չի կարող ձեզ ատել, բայց ինձ ատում է, որովհետև ես վկայում եմ նրա մասին, որ նրա գործերը չար են։","8":"Դուք գնացե՛ք այդ տոնին. ես այդ տոնին չեմ գնում, որովհետև իմ ժամանակը դեռ չի լրացել»։","9":"Հիսուսն այս ասաց նրանց և մնաց Գալիլեայում։","10":"Երբ նրա եղբայրները տոնի համար Երուսաղեմ բարձրացան, այն ժամանակ ինքն էլ այդ տոնին գնաց, բայց ոչ հայտնապես, այլ ծածուկ։","11":"Այդ տոնի ժամանակ հրեաները փնտրում էին նրան ու ասում. «Որտե՞ղ է նա»։","12":"Եվ բազմության մեջ նրա մասին շատ տարակարծություններ կային։ Ոմանք ասում էին՝ «Բարի մարդ է», իսկ ոմանք՝ «Ո՛չ, նա մոլորեցնում է ժողովրդին»։","13":"Ոչ ոք նրա մասին բացահայտ չէր խոսում, որովհետև վախենում էին հրեաներից։","14":"Տոնակատարության կեսին արդեն Հիսուսը տաճար ելավ և ուսուցանում էր։","15":"Հրեաները զարմանում էին ու ասում. «Նա ինչպե՞ս գիտի Սուրբ Գիրքը, երբ բնավ չի ուսանել»։","16":"Հիսուսը նրանց պատասխանեց. «Իմ ուսուցումն իմը չէ, այլ նրանը, ով ինձ ուղարկեց։","17":"Եթե մեկը ցանկանում է նրա կամքը կատարել, նա կհասկանա, թե այս ուսուցումն արդյոք Աստծո՞ւց է, թե՞ ես ինքս ինձնից եմ խոսում։","18":"Ինքն իրենից խոսողն իր փառքն է փնտրում, սակայն ով իրեն ուղարկողի փառքն է փնտրում, նա ճշմարիտ է, և նրա մեջ կեղծ բան չկա։","19":"Չէ՞ որ Օրենքը ձեզ Մովսեսը տվեց, սակայն ձեզանից ոչ ոք Օրենքը չի կատարում։ Ինչո՞ւ եք ուզում ինձ սպանել»։","20":"Բազմությունը պատասխանեց. «Քո մեջ դև՞ ունես. ո՞վ է ուզում քեզ սպանել»։","21":"Հիսուսը պատասխանեց նրանց ու ասաց. «Մի գործ արեցի, և բոլորդ զարմացել եք։","22":"Դրա համար Մովսեսը ձեզ թլփատությունը տվեց (թեև այդ ոչ թե Մովսեսից էր, այլ նահապետներից), և շաբաթ օրով մարդ եք թլփատում։","23":"Արդ, եթե մարդը նույնիսկ շաբաթ օրով է թլփատվում, որպեսզի Մովսեսի օրենքը չխախտվի, ինձ վրա ինչո՞ւ եք բարկանում, որ ես շաբաթ օրով մի մարդու լիովին բժշկեցի։","24":"Ըստ տեսածի մի՛ դատեք, այլ արդա՛ր դատաստան արեք»։","25":"Երուսաղեմցիներից ոմանք ասում էին. «Սա չէ՞ նա, որին ուզում են սպանել։","26":"Բայց ահա նա համարձակ խոսում է, և նրան ոչինչ չեն ասում։ Գուցե իշխանավորներն իրապես ճանաչեցի՞ն, որ սա է Քրիստոսը։","27":"Բայց գիտենք նրան, թե որտեղի՛ց է. իսկ երբ Քրիստոսը գա, ոչ ոք չի իմանալու, թե որտեղի՛ց է»։","28":"Այդժամ Հիսուսը, որ ուսուցանում էր տաճարում, աղաղակեց և ասաց. «Ե՛վ ինձ գիտեք, և՛ գիտեք, թե որտեղի՛ց եմ. ինքս ինձ չեմ եկել. բայց ճշմարիտ է նա, ով ինձ ուղարկել է, նա, որին դուք չգիտեք։","29":"Ես գիտեմ նրան, որովհետև նրանից եմ, և նա՛ ինձ ուղարկեց»։","30":"Այդժամ ուզում էին նրան բռնել, բայց ոչ ոք նրա վրա ձեռքը չերկարեց, որովհետև նրա ժամանակը դեռ չէր եկել։","31":"Ժողովրդից շատերը նրան հավատացին ու ասում էին. «Երբ Քրիստոսը գա, արդյոք ավելի՞ շատ նշաններ պիտի անի, քան սա է անում»։","32":"Փարիսեցիները լսեցին ժողովրդի մեջ նրա մասին եղած շշուկները, և փարիսեցիներն ու քահանայապետները սպասավորներ ուղարկեցին, որպեսզի նրան բռնեն։","33":"Այդժամ Հիսուսն ասաց. «Դեռ մի փոքր ժամանակ ձեզ հետ եմ և ապա գնալու եմ ինձ ուղարկողի մոտ։","34":"Ինձ կփնտրեք, բայց չեք գտնի, և որտեղ ես լինելու եմ, դուք չեք կարող գալ»։","35":"Արդ հրեաները միմյանց ասացին. «Ո՞ւր է գնալու, որ մենք չգտնենք դրան. գուցե գնալու է հույների մեջ ցրված հրեաների մոտ և հույների՞ն է ուսուցանելու։","36":"Ի՞նչ է նշանակում այն խոսքը, որ ասաց. \"Ինձ կփնտրեք, բայց չեք գտնի, և որտեղ ես եմ, դուք չեք կարող գալ\"»։","37":"Եվ տոնի վերջին մեծ օրը Հիսուսը կանգնած էր և աղաղակում էր՝ ասելով. «Եթե մեկը ծարավ է, թող ինձ մոտ գա ու խմի։","38":"Ինչպես Գիրքն է ասում. \"Ով ինձ հավատում է, նրա ներսից կենդանի ջրերի գետեր պիտի բխեն\"»։","39":"Նա այս ասաց՝ նկատի ունենալով Հոգուն, որն ընդունելու էին նրան հավատացողները, որովհետև Սուրբ Հոգին դեռևս չունեին, քանի որ Հիսուսը դեռ փառավորված չէր։","40":"Արդ ժողովրդի միջից շատերը, երբ լսում էին այս խոսքերը, ասում էին. «Իրապես որ նա մարգարեն է»։","41":"Ուրիշներն ասում էին. «Սա է Քրիստոսը»։ Իսկ մնացածն էլ ասում էին. «Մի՞թե Քրիստոսը Գալիլեայից է գալու.","42":"չէ՞ որ Գիրքն ասում է. \"Քրիստոսը գալու է Դավթի սերնդից ու Բեթլեհեմ գյուղից, որտեղից Դավիթն էր\"»։","43":"Եվ ժողովրդի մեջ նրա պատճառով պառակտում եղավ։","44":"Նրանցից ոմանք ուզեցին բռնել նրան, բայց ոչ ոք նրա վրա ձեռքը չերկարեց։","45":"Արդ, սպասավորները վերադարձան քահանայապետների ու փարիսեցիների մոտ, և սրանք ասացին նրանց. «Ինչո՞ւ նրան չբերեցիք»։","46":"Սպասավորները պատասխանեցին. «Ոչ մի մարդ երբեք այդպես չի խոսել, ինչպես այս մարդը»։","47":"Փարիսեցիները նրանց պատասխանեցին. «Մի՞թե դուք էլ եք մոլորվել։","48":"Մի՞թե իշխանավորներից կամ փարիսեցիներից մեկը հավատաց նրան,","49":"բացի այս ժողովրդից, որ չգիտի օրենքը և դրա համար նզովված է»։","50":"Նիկոդեմոսը, որ նախկինում գիշերով Հիսուսի մոտ էր գնացել և նրանցից մեկն էր, ասաց նրանց.","51":"«Մի՞թե մեր օրենքը դատապարտում է մարդուն՝ առանց նախապես նրան լսելու կամ իմանալու, թե ի՛նչ է արել»։","52":"Նրանք պատասխանեցին նրան. «Գուցե դու է՞լ ես Գալիլեայից. քննի՛ր ու տե՛ս, որ Գալիլեայից մարգարե դուրս չի գալիս»։","53":"Եվ ամեն մեկն իր տուն գնաց։"},"8":{"1":"Հիսուսը Ձիթենյաց լեռը գնաց։","2":"Առավոտյան դարձյալ տաճար եկավ, և ամբողջ ժողովուրդը նրա մոտ էր գալիս։ Նա նստած ուսուցանում էր նրանց։","3":"Դպիրներն ու փարիսեցիները նրա մոտ շնության մեջ բռնված մի կնոջ բերեցին և նրան մեջտեղ կանգնեցնելով՝","4":"ասացին Հիսուսին. «Վարդապե՛տ, այս կինը բռնվել է հայտնապես շնանալիս։","5":"Մովսեսը Օրենքում մեզ պատվիրել է քարկոծել այսպիսիներին։ Հիմա դու ի՞նչ ես ասում»։","6":"Բայց նրան փորձելու համար էին այդ ասում, որպեսզի նրան ամբաստանելու պատճառ ունենան։ Հիսուսը, գետնին նայելով, մատով գրում էր հողի վրա։","7":"Բայց երբ պնդում էին իրենց հարցումը, նա վեր նայեց ու ասաց. «Ձեզանից ով անմեղ է, թող առաջինը նա՛ քար գցի դրա վրա»։","8":"Եվ դարձյալ ցած նայելով՝ գրում էր հողի վրա։","9":"Սակայն նրանք, այս լսելով, մեկը մյուսի հետևից՝ մեծից փոքր, ելան գնացին։ Եվ մնացին միայն Հիսուսն ու մեջտեղում կանգնած կինը։","10":"Այդժամ Հիսուսը վեր նայեց և նրան ասաց. «Ո՛վ կին, քեզ ամբաստանողները որտե՞ղ են. քեզ ոչ ոք չդատապարտե՞ց»։","11":"Իսկ նա ասաց. «Ոչ ոք, Տե՛ր»։ Հիսուսը նրան ասաց. «Ոչ էլ ես եմ քեզ դատապարտում. գնա՛ և այսուհետև մեղք մի՛ գործիր»։","12":"Արդ Հիսուսը նորից խոսեց նրանց հետ ու ասաց. «Ես եմ աշխարհի լույսը. ով իմ հետևից գա, նա խավարի մեջ չի քայլի, այլ կյանքի լույսը կընդունի»։","13":"Այդժամ փարիսեցիները նրան ասացին. «Դու ինքդ ես քո մասին վկայում. քո վկայությունը ճշմարիտ չէ»։","14":"Հիսուսը պատասխանեց նրանց ու ասաց. «Թեև ես եմ իմ մասին վկայում, իմ վկայությունը ճշմարիտ է, որովհետև գիտեմ, թե որտեղի՛ց եմ եկել և ո՛ւր եմ գնում։ Իսկ դուք չգիտեք, թե որտեղի՛ց եկա և ո՛ւր եմ գնում։","15":"Դուք ըստ մարմնի եք դատում, իսկ ես ոչ ոքի չեմ դատում։","16":"Եվ եթե ես դատեմ էլ, իմ դատաստանը ճշմարիտ է, որովհետև ես մենակ չեմ, այլ ես եմ ու Հայրը, որն ուղարկեց ինձ։","17":"Եվ ձեր օրենքում իսկ գրված է. \"Երկու մարդկանց վկայությունը ճշմարիտ է\"։","18":"Ես ինքս եմ վկայում իմ մասին, և իմ մասին վկայում է նաև Հայրը, որն ուղարկեց ինձ»։","19":"Արդ նրան հարցրին. «Որտե՞ղ է քո Հայրը»։ Հիսուսը պատասխանեց. «Դուք ո՛չ ինձ գիտեք, ո՛չ էլ իմ Հորը. եթե ինձ ճանաչեիք, իմ Հորն էլ կճանաչեիք»։","20":"Հիսուսն այս խոսքերն ասաց գանձատանը, երբ նրանց ուսուցանում էր տաճարում։ Եվ նրան ոչ ոք չբռնեց, որովհետև դեռ նրա ժամը չէր հասել։","21":"Հիսուսը դարձյալ ասաց նրանց. «Ես գնում եմ. ինձ կփնտրեք և ձեր մեղքերի մեջ կմեռնեք. ուր որ ես գնում եմ, դուք չեք կարող գալ»։","22":"Հրեաներն ասում էին. «Գուցե ինքնասպա՞ն է լինելու, որովհետև ասում է. \"Ուր որ ես գնում եմ, դուք չեք կարող գալ\"»։","23":"Եվ նրանց ասաց. «Դուք ներքևից եք, իսկ ես՝ վերևից. դուք այս աշխարհից եք, իսկ ես այս աշխարհից չեմ։","24":"Արդ ես ձեզ ասացի. \"Ձեր մեղքերի մեջ կմեռնեք\", որովհետև եթե չհավատաք, որ իրապես ես եմ, կմեռնեք ձեր մեղքերի մեջ»։","25":"Այդժամ նրան հարցրին. «Ո՞վ ես դու»։ Հիսուսը նրանց ասաց. «Նա, որ սկզբից ևեթ շարունակ խոսում էր ձեզ հետ։","26":"Ձեր մասին խոսելու և դատելու շատ բան ունեմ։ Սակայն նա, ով ինձ ուղարկել է, ճշմարիտ է, և ինչ որ լսել եմ նրանից, այն եմ խոսում աշխարհում»։","27":"Նրանք չհասկացան, որ Հոր մասին էր ասում իրենց։","28":"Հիսուսը նրանց ասաց. «Երբ Մարդու Որդուն բարձրացնեք, այն ժամանակ պիտի իմանաք, որ ես եմ, և ինքս ինձանից ոչինչ չեմ անում, այլ ինչպես իմ Հայրն ինձ սովորեցրեց, այն եմ խոսում։","29":"Ով ինձ ուղարկեց, ինձ հետ է. ինձ մենակ չի թողել, որովհետև ես միշտ անում եմ այն, ինչ նրան հաճելի է»։","30":"Երբ այս խոսքերն ասաց, շատերը հավատացին նրան։","31":"Այդժամ Հիսուսն իրեն հավատացած հրեաներին ասաց. «Եթե դուք հավատարիմ մնաք իմ խոսքին, իմ ճշմարիտ աշակերտները կլինեք։","32":"Կճանաչեք ճշմարտությունը, և ճշմարտությունը կազատի ձեզ»։","33":"Նրան պատասխանեցին. «Մենք Աբրահամի որդիներն ենք և երբեք ոչ ոքի չենք ծառայել. դու ինչպե՞ս ես ասում, թե ազատ կլինեք»։","34":"Հիսուսը նրանց պատասխանեց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. ամեն ոք, ով մեղք է գործում, մեղքի ծառա է։","35":"Իսկ ծառան ընդմիշտ տանը չի մնում. որդին է ընդմիշտ մնում։","36":"Արդ, եթե Որդին ձեզ ազատի, ճշմարտապես ազատ կլինեք։","37":"Գիտեմ, որ Աբրահամի որդիներն եք, բայց ուզում եք ինձ սպանել, որովհետև իմ խոսքը ձեր մեջ տեղ չունի։","38":"Ես ասում եմ այն, ինչ տեսել եմ իմ Հոր մոտ, իսկ դուք անում եք այն, ինչ տեսել եք ձեր հորից»։","39":"Պատասխանեցին նրան ու ասացին. «Մեր հայրն Աբրահամն է»։ Հիսուսը նրանց ասաց. «Եթե Աբրահամի որդիներ լինեիք, Աբրահամի գործերը կկատարեիք։","40":"Բայց հիմա ուզում եք սպանել ինձ, մի մարդու, որ ճշմարտությունն է ձեզ ասել, և որը ես Աստծուց լսեցի. այդ բանն Աբրահամը չարեց։","41":"Դուք ձեր հոր գործերն եք կատարում»։ Եվ նրան ասացին. «Մենք պոռնկությունից չենք ծնվել. մեկ Հայր ունենք՝ Աստված»։","42":"Հիսուսը նրանց ասաց. «Եթե Աստված ձեր Հայրը լիներ, ինձ կսիրեիք, որովհետև ես Աստծուց ելա ու եկա. ես ինքս ինձ չեկա, այլ նա՛ ինձ ուղարկեց։","43":"Դուք իմ խոսքերն ինչո՞ւ չեք հասկանում. որովհետև չեք կարողանում իմ խոսքը լսել։","44":"Ձեր ունեցած հայրը սատանան է, և ինչ ձեր հայրը ցանկանում է, այդ եք ուզում կատարել։ Նա սկզբից ևեթ մարդասպան էր և ճշմարտության մեջ չմնաց, որովհետև նրա մեջ ճշմարտություն չկա։ Երբ նա ստում է, ինքն իրեն է արտահայտում, որովհետև ստախոս է և կեղծիքի հայրը։","45":"Սակայն ես, որ ճշմարտությունն եմ ասում, ինձ չեք հավատում։","46":"Ձեզանից ո՞վ կարող է ինձ մեղքի համար հանդիմանել. բայց եթե ճշմարտությունն եմ ասում, ինչո՞ւ ինձ չեք հավատում։","47":"Ով Աստծուց է, Աստծու խոսքերն է լսում. դուք Աստծուց չեք, դրա համար դուք չեք լսում»։","48":"Հրեաները պատասխանեցին նրան. «Մենք ճիշտ չե՞նք, երբ ասում ենք, որ դու սամարացի ես ու դև ունես»։","49":"Հիսուսը պատասխանեց. «Ես դև չունեմ, այլ պատվում եմ իմ Հորը, իսկ դուք ինձ անարգում եք։","50":"Սակայն ես իմ փառքը չեմ փնտրում. կա մեկը, որ այն փնտրում է և դատում։","51":"Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. եթե մեկն իմ խոսքը պահի, նա մահ չի տեսնի հավիտյան»։","52":"Հրեաները նրան ասացին. «Հիմա իմացանք, որ դև ունես։ Աբրահամը մեռավ, մարգարեները՝ նույնպես, իսկ դու ասում ես. \"Եթե մեկն իմ խոսքը պահի, հավիտյան մահ չի ճաշակի\"։","53":"Գուցե դու ավելի մե՞ծ ես, քան մեր հայր Աբրահամը, որ մեռավ, մարգարեները ևս մեռան։ Իսկ ի՞նչ ես կարծում, դու ո՞վ ես»։","54":"Հիսուսը պատասխանեց. «Եթե ես ինքս ինձ փառավորեմ, իմ փառքը ոչինչ է։ Ինձ փառավորողը Հայրն է, նա, ում մասին դուք ասում եք՝ \"Մեր Աստվածն է\"։","55":"Եվ չեք ճանաչում նրան, իսկ ես նրան գիտեմ, և եթե ասեմ, որ ես նրան չգիտեմ, ձեզ նման ստախոս կլինեմ. բայց ես գիտեմ նրան ու նրա խոսքը պահում եմ։","56":"Աբրահամը՝ ձեր հայրը, ցնծում էր այն մտքից, որ կարող է իմ օրերը տեսնել. նա տեսավ և ուրախացավ»։","57":"Ապա հրեաները նրան ասացին. «Դու դեռ հիսուն տարեկան չկաս և Աբրահամի՞ն ես տեսել»։","58":"Հիսուսը նրանց ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. ես կամ նախքան Աբրահամը»։","59":"Այդժամ նրանք քարեր վերցրին, որ նրա վրա նետեն, բայց Հիսուսը թաքնվեց և տաճարից դուրս գնաց։"},"9":{"1":"Մինչ Հիսուսն անցնում էր, ի ծնե կույր մի մարդու տեսավ։","2":"Նրա աշակերտները հարցրին նրան. «Ռա՛բբի, ո՞վ է մեղանչել, որ նա կույր է ծնվել. նա՞, թե՞ նրա ծնողները»։","3":"Հիսուսը պատասխանեց. «Ո՛չ նա է մեղանչել, ո՛չ էլ նրա ծնողները, այլ որպեսզի նրա միջոցով Աստծու գործերը հայտնի դառնան։","4":"Քանի դեռ ցերեկ է, ես պետք է կատարեմ ինձ ուղարկողի գործերը։ Գիշերը գալիս է, և այն ժամանակ ոչ ոք չի կարող գործել։","5":"Քանի դեռ աշխարհում եմ, լույսն եմ աշխարհի»։","6":"Այս ասելով՝ թքեց գետնին, թքից կավ շինեց և այն քսեց կույրի աչքերին","7":"ու նրան ասաց. «Գնա լվացվի՛ր Սիլովամի ավազանում» (որ նշանակում է «Ուղարկված»)։ Արդ նա գնաց, լվացվեց ու երբ վերադարձավ, տեսնում էր։","8":"Այդժամ հարևաններն ու նրանք, որ նախկինում նրան տեսել էին, որ մուրացիկ էր, ասում էին. «Այդ նա չէ՞, որ նստած մուրում էր»։","9":"Ոմանք ասում էին՝ «Նա է», ուրիշներն էլ՝ «Նրան նման է»։ Սակայն ինքն ասում էր՝ «Ես եմ»։","10":"Արդ նրան հարցնում էին. «Հապա աչքերդ ինչպե՞ս բացվեցին»։","11":"Նա պատասխանեց. «Մի մարդ, անունը՝ Հիսուս, կավ շինեց, աչքերիս քսեց և ինձ ասաց. \"Գնա՛ Սիլովամ ու լվացվի՛ր\"։ Գնացի, լվացվեցի և տեսնում եմ»։","12":"Եվ նրան ասացին. «Որտե՞ղ է նա»։ Ասաց. «Չգիտեմ»։","13":"Նրան, որ մի ժամանակ կույր էր, փարիսեցիների մոտ տարան։","14":"Օրը շաբաթ էր, երբ Հիսուսը կավ շինեց ու նրա աչքերը բացեց։","15":"Փարիսեցիները ևս նրան կրկին հարցրին, թե ինչպե՛ս եղավ, որ նա տեսնում է։ Եվ նա ասաց նրանց. «Աչքերիս վրա կավ դրեց, լվացվեցի և տեսնում եմ»։","16":"Փարիսեցիներից ոմանք ասացին. «Այդ մարդն Աստծուց չէ, քանի որ շաբաթ օրը չի պահում»։ Իսկ ուրիշներն ասում էին. «Ինչպե՞ս կարող է մեղավոր մարդը այսպիսի նշաններ անել»։ Եվ նրանց մեջ երկպառակություն կար։","17":"Այդժամ կույրին դարձյալ հարցրին. «Իսկ դու ի՞նչ ես ասում նրա մասին, քանի որ նա աչքերդ բացեց»։ Նա ասաց. «Մարգարե է»։","18":"Սակայն հրեաները չէին հավատում, թե նա կույր էր ու սկսեց տեսնել, մինչև որ կանչեցին աչքերը բացվածի ծնողներին","19":"և նրանց հարցրին. «Սա՞ է ձեր որդին, որի մասին դուք ասում եք, թե կույր է ծնվել. իսկ հիմա ինչպե՞ս է տեսնում»։","20":"Նրա ծնողները պատասխանեցին ու ասացին. «Գիտենք, որ սա մեր որդին է և որ կույր է ծնվել,","21":"բայց թե հիմա ինչպե՛ս է տեսնում, չգիտենք, կամ թե ո՛վ բացեց նրա աչքերը, նույնպես չգիտենք. նրա՛ն հարցրեք. ինքը չափահաս է, թող ինքն իր մասին խոսի»։","22":"Նրա ծնողներն այս ասացին, որովհետև հրեաներից վախենում էին, քանի որ հրեաներն արդեն համաձայնության էին եկել, որ եթե մեկը նրան Քրիստոս խոստովանի, ժողովարանից հեռացվի։","23":"Դրա համար նրա ծնողներն ասացին. «Ինքը չափահաս է, իրե՛ն հարցրեք»։","24":"Հետո երկրորդ անգամ կանչեցին այն մարդուն, որ կույր էր, ու նրան ասացին. «Ասա՛ ճշմարտությունն Աստծու առաջ։ Մենք գիտենք, որ այն մարդը մեղավոր է»։","25":"Իսկ նա պատասխանեց. «Թե մեղավոր է, ես չգիտեմ. մի բան գիտեմ, որ կույր էի և այժմ տեսնում եմ»։","26":"Եվ դարձյալ ասացին նրան. «Քեզ ի՞նչ արեց, աչքերդ ինչպե՞ս բացեց»։","27":"Նրանց պատասխանեց. «Ձեզ արդեն ասացի, բայց չլսեցիք. ի՞նչ եք դարձյալ ուզում լսել. գուցե դուք է՞լ եք ցանկանում նրան աշակերտել»։","28":"Նրանք նախատեցին նրան ու ասացին. «Դու ես նրա աշակերտը, իսկ մենք Մովսեսի աշակերտներն ենք։","29":"Մենք գիտենք, որ Աստված խոսեց Մովսեսի հետ, իսկ սրան չգիտենք, թե որտեղի՛ց է»։","30":"Մարդը պատասխանեց ու ասաց նրանց. «Դա է զարմանալին, որ դուք չգիտեք, թե այդ մարդը որտեղի՛ց է, իսկ նա իմ աչքերը բացեց։","31":"Գիտենք, որ Աստված մեղավորներին չի լսում, բայց եթե մեկն աստվածապաշտ է ու նրա կամքը կատարում է, նրան լսում է։","32":"Աշխարհի սկզբից ի վեր լսված չէ, որ մեկը ի ծնե կույրի աչքերը բացած լինի։","33":"Եթե նա Աստծուց չլիներ, ոչինչ չէր կարող անել»։","34":"Պատասխանեցին ու նրան ասացին. «Դու, որ ամբողջովին մեղքի մեջ ես ծնվել, դո՞ւ ես մեզ դաս տալիս»։ Եվ նրան դուրս հանեցին։","35":"Հիսուսը լսեց, որ նրան դուրս են հանել, և երբ նրան գտավ, ասաց. «Դու Աստծու Որդուն հավատո՞ւմ ես»։","36":"Նա պատասխանեց ու ասաց. «Տե՛ր, իսկ ո՞վ է նա, որ նրան հավատամ»։","37":"Հիսուսը նրան ասաց. «Ե՛վ տեսար նրան, և՛ քեզ հետ խոսողն էլ նա է»։","38":"Եվ նա ասաց. «Հավատում եմ, Տե՛ր», ու երկրպագեց նրան։","39":"Հիսուսն ասաց. «Ես այս աշխարհ եկա դատաստանի համար, որպեսզի ովքեր չեն տեսնում, տեսնեն, իսկ ովքեր տեսնում են, կուրանան»։","40":"Փարիսեցիներից ոմանք, որ նրա հետ այնտեղ էին, այս լսեցին ու նրան ասացին. «Մի՞թե մենք էլ կույր ենք»։","41":"Հիսուսը նրանց ասաց. «Եթե կույր լինեիք, մեղք չէիք ունենա. բայց հիմա ասում եք՝ \"Տեսնում ենք\", և ձեր մեղքը ձեր մեջ է մնում»։"},"10":{"1":"«Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. ով ոչխարների փարախը դռնով չի մտնում, այլ ուրիշ տեղով է բարձրանում, նա գող է ու ավազակ։","2":"Սակայն ով դռնով է մտնում, նա ոչխարների հովիվն է։","3":"Դռնապանը նրա համար բացում է դուռը, և ոչխարները լսում են նրա ձայնը։ Նա իր ոչխարներին կանչում է անուն առ անուն և նրանց դուրս է հանում։","4":"Եվ երբ իր բոլոր ոչխարներին դուրս է հանում, գնում է նրանց առջևից, իսկ ոչխարները հետևում են նրան, որովհետև ճանաչում են նրա ձայնը։","5":"Բայց օտարի հետևից չեն գնա, այլ նրանից կփախչեն, որովհետև օտարների ձայնը չեն ճանաչում»։","6":"Հիսուսը նրանց այս առակն ասաց, բայց նրանք չէին հասկանում, թե ինչի՛ համար էր նա այդ ասում իրենց։","7":"Հիսուսը դարձյալ ասաց նրանց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. ես եմ ոչխարների դուռը։","8":"Բոլոր նրանք, ովքեր ինձանից առաջ են եկել, գողեր ու ավազակներ են, ուստի ոչխարները նրանց չեն լսել։","9":"Ես եմ դուռը. եթե մեկն իմ միջով ներս մտնի, կփրկվի. կմտնի, կելնի և արոտ կգտնի։","10":"Գողը գալիս է միայն գողանալու, մորթելու և ոչնչացնելու համար, սակայն ես եկա, որ իմ ոչխարները կյանք ունենան և առատ կյանք։","11":"Ես եմ բարի հովիվը. բարի հովիվը իր կյանքն է տալիս ոչխարների համար։","12":"Բայց վարձկանը, որ հովիվ չէ, և ոչխարներն էլ իրենը չեն, երբ տեսնում է, որ գայլը գալիս է, թողնում է ոչխարներին ու փախչում։ Եվ գայլը հափշտակում է նրանց ու ցրում։","13":"Իսկ վարձկանը փախչում է, որովհետև վարձկան է և ոչխարներին հոգ չի տանում։","14":"Ես եմ բարի հովիվը, և ես ճանաչում եմ իմ ոչխարներին, ու նրանք էլ ճանաչում են ինձ։","15":"Ինչպես Հայրն է ինձ ճանաչում, ես էլ ճանաչում եմ Հորը և իմ կյանքը տալիս եմ ոչխարների համար։","16":"Ուրիշ ոչխարներ էլ ունեմ, որոնք այս փարախից չեն. նրանց ևս պետք է առաջնորդեմ, և իմ ձայնը կլսեն ու կդառնան մեկ հոտ՝ մեկ հովիվով։","17":"Իմ Հայրն ինձ սիրում է այն բանի համար, որ ես իմ կյանքը տալիս եմ, որպեսզի այն վերստին ստանամ։","18":"Այն ինձանից ոչ ոք չի վերցնում, այլ ես ինքս եմ այն տալիս. ես իշխանություն ունեմ այն տալու և իշխանություն ունեմ վերստին այն վերցնելու. ես այս պատվերն իմ Հորից եմ ստացել»։","19":"Արդ, այս խոսքերի պատճառով հրեաների մեջ դարձյալ երկպառակություն առաջացավ։","20":"Նրանցից շատերն ասում էին. «Նա դև ունի և մոլագար է. ինչո՞ւ եք դրան լսում»։","21":"Ուրիշներն էլ ասում էին. «Այս խոսքերը դիվահարի խոսքեր չեն. մի՞թե դևը կարող է կույրի աչքերը բացել»։","22":"Այդ ժամանակ Երուսաղեմում Նավակատիքի տոնն էր։ Ձմեռ էր։","23":"Հիսուսը քայլում էր տաճարում՝ Սողոմոնի սրահում։","24":"Հրեաները նրա շուրջը հավաքվեցին ու ասացին. «Մինչև ե՞րբ ես մեր հոգին տանջելու. եթե դու ես Քրիստոսը, համարձակ ասա՛ մեզ»։","25":"Հիսուսը նրանց պատասխանեց. «Ձեզ ասացի, ու չեք հավատում. այն գործերը, որ իմ Հոր անունով կատարում եմ, դրանք իմ մասին են վկայում։","26":"Բայց դուք չեք հավատում, որովհետև իմ ոչխարներից չեք։","27":"Իմ ոչխարներն իմ ձայնը լսում են, ու ես նրանց ճանաչում եմ, և նրանք գալիս են իմ հետևից։","28":"Եվ ես նրանց հավիտենական կյանք եմ տալիս, և նրանք հավիտյան չեն կորչի, ու ոչ ոք նրանց իմ ձեռքից չի հափշտակի։","29":"Իմ Հայրը, որ նրանց ինձ տվեց, բոլորից մեծ է։ Ոչ ոք չի կարող նրանց իմ Հոր ձեռքից հափշտակել։","30":"Ես և Հայրը մի ենք»։","31":"Հրեաները դարձյալ քարեր վերցրին, որ նրան քարկոծեն։","32":"Հիսուսը նրանց ասաց. «Ձեզ բազում բարի գործեր ցույց տվեցի իմ Հոր կողմից. դրանցից ո՞ր գործի համար եք ինձ քարկոծում»։","33":"Հրեաները պատասխանեցին. «Քեզ ոչ թե բարի գործի համար ենք քարկոծում, այլ հայհոյության, որ դու, մարդ լինելով, ինքդ քեզ Աստծու տեղ ես դնում»։","34":"Հիսուսը նրանց պատասխանեց. «Ձեր օրենքում գրված չէ՞. \"Ես ասացի՝ աստվածներ եք\" (Սաղ. 82.6)։","35":"Գրքում աստվածներ են կոչվում նրանք, որոնց ուղղված է Աստծու խոսքը։ Իսկ այն, ինչ գրված է Գրքում, չի կարող ջնջվել։","36":"Նրան, ում Հայրը սրբացրեց ու աշխարհ ուղարկեց, դուք ասում եք՝ հայհոյում ես. նրա՞ համար, որ ասացի, թե Աստծու Որդին եմ։","37":"Եթե իմ Հոր գործե՛րը չեմ կատարում, ինձ մի՛ հավատացեք։","38":"Իսկ եթե կատարում եմ, թեկուզ ինձ չհավատաք, գոնե գործերի՛ն հավատացեք, որպեսզի իմանաք ու ճանաչեք, որ Հայրն իմ մեջ է, ու ես՝ Հոր մեջ»։","39":"Դարձյալ ուզում էին բռնել Հիսուսին, բայց նա ազատվեց նրանց ձեռքից։","40":"Դարձյալ գնաց Հորդանանի մյուս կողմը, որտեղ նախկինում Հովհաննեսն էր մկրտում։ Եվ Հիսուսն այնտեղ էր մնում։","41":"Շատերն էին նրա մոտ գալիս և ասում. «Հովհաննեսը ոչ մի նշան չի արել։ Բայց այն ամենը, ինչ Հովհաննեսն ասել է Հիսուսի մասին, ճշմարիտ էր»։","42":"Եվ այնտեղ շատերը հավատացին նրան։"},"11":{"1":"Ղազարոս անունով մի հիվանդ կար Բեթանիայից՝ Մարիամի ու նրա քույր Մարթայի գյուղից։","2":"Այն Մարիամն էր, որ Տիրոջը յուղով օծեց և նրա ոտքերն իր մազերով սրբեց։ Նրա եղբայր Ղազարոսը հիվանդ էր։","3":"Արդ նրա քույրերը Հիսուսին լուր ուղարկեցին ու ասացին. «Տե՛ր, քո սիրելի ընկերը հիվանդացել է»։","4":"Երբ Հիսուսը լսեց, ասաց. «Այդ հիվանդությունը մահաբեր չէ, այլ Աստծու փառքը հայտնի դարձնելու համար է, որպեսզի Աստծու Որդին նրա միջոցով փառավորվի»։","5":"Հիսուսը սիրում էր Մարթային, նրա քրոջն ու Ղազարոսին։","6":"Եվ երբ լսեց, որ նա հիվանդ է, երկու օր մնաց այնտեղ, որտեղ հիվանդն էր։","7":"Դրանից հետո աշակերտներին ասաց. «Եկե՛ք նորից Հուդա գնանք»։","8":"Աշակերտները նրան ասացին. «Ռա՛բբի, հրեաները մինչև հիմա ուզում են քեզ քարկոծել, և դու դարձյալ այնտե՞ղ ես գնում»։","9":"Հիսուսը պատասխանեց. «Չէ՞ որ ցերեկը տասներկու ժամ ունի։ Եթե մեկը ցերեկով է քայլում, չի սայթաքում, որովհետև այս աշխարհի լույսն է տեսնում։","10":"Իսկ եթե մեկը գիշերով է քայլում, սայթաքում է, որովհետև նրա մեջ լույս չկա»։","11":"Այս ասելուց հետո նրանց ասաց. «Մեր բարեկամը՝ Ղազարոսը, ննջել է, սակայն ես գնում եմ, որ նրան արթնացնեմ»։","12":"Այդժամ նրա աշակերտներն ասացին. «Տե՛ր, եթե ննջել է, ապա կառողջանա»։","13":"Բայց Հիսուսը խոսում էր նրա մահվան մասին, իսկ աշակերտները կարծում էին, թե սովորական քնի մասին է խոսում։","14":"Այն ժամանակ Հիսուսը նրանց բացահայտ ասաց. «Ղազարոսը մահացել է։","15":"Եվ ես ձեզ համար ուրախ եմ, որ հավատալու եք, քանի որ ես այնտեղ չէի, երբ նա մահացավ. սակայն եկե՛ք գնանք նրա մոտ»։","16":"Այդժամ Թովմասը, որ «Երկվորյակ» էր կոչվում, աշակերտակիցներին ասաց. «Մե՛նք էլ գնանք նրա հետ մեռնելու»։","17":"Երբ Հիսուսը եկավ, նրան արդեն չորս օր գերեզմանի մեջ դրված գտավ։","18":"Բեթանիան Երուսաղեմին շուրջ տասնհինգ ասպարեզ էր մոտ։","19":"Եվ հրեաներից շատերն էին եկել Մարթայի ու Մարիամի մոտ՝ իրենց եղբոր համար նրանց մխիթարելու։","20":"Արդ երբ Մարթան լսեց, որ Հիսուսը գալիս է, գնաց նրան ընդառաջ, իսկ Մարիամը տանը նստած էր։","21":"Մարթան Հիսուսին ասաց. «Տե՛ր, եթե այստեղ լինեիր, իմ եղբայրը չէր մահանա։","22":"Բայց հիմա էլ գիտեմ, որ Աստծուց ինչ էլ որ խնդրես, Աստված կտա քեզ»։","23":"Հիսուսը նրան ասաց. «Քո եղբայրը հարություն կառնի»։","24":"Մարթան նրան ասաց. «Գիտեմ, որ հարություն կառնի վերջին օրը՝ հարության ժամանակ»։","25":"Հիսուսը նրան ասաց. «Ես եմ հարությունը և կյանքը. ով հավատում է ինձ, թեկուզ և մեռնի, կապրի։","26":"Եվ ամեն ոք, ով կենդանի է ու ինձ հավատում է, հավիտյան չի մեռնի։ Սրան հավատո՞ւմ ես»։","27":"Մարթան նրան ասաց. «Այո՛, Տե՛ր, ես հավատացել եմ, որ դու ես Քրիստոսը՝ Աստծու Որդին, որ աշխարհ էիր գալու»։","28":"Եվ այս ասելուց հետո գնաց, իր քրոջը՝ Մարիամին, ծածուկ կանչեց ու ասաց. «Վարդապետը եկել է ու քեզ է կանչում»։","29":"Հենց նա լսեց, արագ վեր կացավ ու Հիսուսի մոտ եկավ։","30":"Հիսուսը դեռ գյուղ չէր հասել, այլ այնտեղ էր, որտեղ Մարթան դիմավորել էր նրան։","31":"Արդ այն հրեաները, որ նրա հետ տանն էին ու մխիթարում էին նրան, երբ տեսան, որ Մարիամը շուտափույթ վեր կացավ գնաց, իրենք ևս հետևեցին նրան՝ կարծելով, թե գերեզման է գնում, որ այնտեղ լաց լինի։","32":"Բայց երբ Մարիամը եկավ այնտեղ, որտեղ Հիսուսն էր, ու նրան տեսավ, նրա ոտքերն ընկավ ու ասաց. «Տե՛ր, եթե այստեղ լինեիր, իմ եղբայրը չէր մահանա»։","33":"Երբ Հիսուսը տեսավ, որ նա և նրա հետ եկած հրեաները լաց են լինում, հոգով խռովվեց և հուզվեց։","34":"Եվ Հիսուսն ասաց. «Որտե՞ղ դրեցիք նրան»։ Նրան ասացին. «Տե՛ր, արի՛ ու տե՛ս»։","35":"Հիսուսն արտասվեց։","36":"Այդժամ հրեաներն ասում էին. «Տես ինչպե՜ս էր նրան սիրում»։","37":"Նրանցից ոմանք ասում էին. «Նա, որ կույրի աչքերը բացեց, չէ՞ր կարող այնպես անել, որ Ղազարոսն էլ չմեռներ»։","38":"Արդ Հիսուսը, դարձյալ ինքն իր մեջ խռովվելով, գերեզման եկավ։ Դա մի քարայր էր՝ վրան մի քար դրված։","39":"Հիսուսն ասաց. «Վերցրե՛ք այդ քարը»։ Մեռածի քույրը՝ Մարթան, նրան ասաց. «Տե՛ր, հիմա արդեն նեխած կլինի, որովհետև չորս օրվա է»։","40":"Հիսուսը նրան ասաց. «Քեզ չասացի՞, որ եթե հավատաս, Աստծու փառքը կտեսնես»։","41":"Եվ քարը բարձրացրին։ Հիսուսն աչքերը վեր բարձրացրեց ու ասաց. «Հա՛յր, շնորհակալ եմ քեզ, որ ինձ լսեցիր։","42":"Ես գիտեի, որ միշտ լսում ես ինձ. բայց դա ասացի շուրջս կանգնած ժողովրդի համար, որպեսզի հավատան, որ դո՛ւ ինձ ուղարկեցիր»։","43":"Եվ երբ այս ասաց, բարձրաձայն աղաղակեց. «Ղազարո՛ս, դո՛ւրս եկ»։","44":"Եվ մեռելը դուրս ելավ՝ ձեռքերն ու ոտքերը պատանով կապված և երեսը թաշկինակով պատված։ Հիսուսը նրանց ասաց. «Դրան արձակե՛ք ու թողե՛ք, որ քայլի»։","45":"Արդ հրեաներից շատերը, որ Մարիամի մոտ էին եկել, երբ տեսան, թե Հիսուսն ի՛նչ արեց, հավատացին նրան։","46":"Բայց նրանցից ոմանք փարիսեցիների մոտ գնացին ու պատմեցին նրանց, ինչ որ Հիսուսն արեց։","47":"Այդժամ քահանայապետներն ու փարիսեցիները ժողով գումարեցին ու ասացին. «Ի՞նչ անենք։ Այդ մարդը բազում նշաններ է կատարում։","48":"Եթե նրան այդպես թողնենք, բոլորը նրան կհավատան, իսկ այդ ժամանակ հռոմեացիները կգան, կվերացնեն և՛ մեր տաճարը, և՛ մեր ազգը»։","49":"Նրանցից մեկը՝ Կայիափան, որ այդ տարվա քահանայապետն էր, նրանց ասաց. «Դուք ոչինչ չեք հասկանում։","50":"Եվ չեք էլ մտածում, որ մեզ համար լավ է, որ մեկ մարդ մեռնի ժողովրդի համար, քան ամբողջ ազգը կորչի»։","51":"Բայց նա այդ իրենից չասաց, այլ որովհետև այդ տարվա քահանայապետն էր, մարգարեացավ, որ Հիսուսը պիտի մեռներ ազգի համար։","52":"Եվ ոչ միայն ազգի համար, այլ որպեսզի միավորեր նաև Աստծու ցրված զավակներին։","53":"Արդ այդ օրվանից որոշեցին նրան սպանել։","54":"Եվ Հիսուսը հրեաների մեջ համարձակ չէր շրջում, այլ այնտեղից գնաց անապատին մոտ մի քաղաք, որ Եփրաիմ էր կոչվում, և իր աշակերտների հետ այնտեղ էր մնում։","55":"Մոտենում էր հրեաների Զատիկը։ Այդ գավառից շատերը Զատկից առաջ Երուսաղեմ բարձրացան, որպեսզի իրենց ծիսական մաքրումը կատարեն։","56":"Նրանք Հիսուսին էին փնտրում ու մինչ տաճարում կանգնած էին, միմյանց ասում էին. «Ի՞նչ եք կարծում, արդյոք այս տոնին չի՞ գա»։","57":"Իսկ քահանայապետներն ու փարիսեցիները հրահանգել էին, որ եթե որևէ մեկն իմանա նրա տեղը, հայտնի իրենց, որպեսզի նրան բռնեն։"},"12":{"1":"Զատկից վեց օր առաջ Հիսուսը եկավ Բեթանիա, որտեղ ապրում էր Ղազարոսը, և որին նա մեռելներից հարություն էր տվել։","2":"Այնտեղ նրա համար ընթրիք պատրաստեցին։ Մարթան սպասարկում էր, իսկ Ղազարոսը նրա հետ սեղան նստածներից մեկն էր։","3":"Արդ Մարիամը մեկ լիտր նարդոսի ազնիվ, թանկարժեք յուղ վերցրեց, օծեց Հիսուսի ոտքերը և իր մազերով սրբեց նրա ոտքերը։ Եվ տունը լցվեց յուղի բուրմունքով։","4":"Հիսուսի աշակերտներից մեկը՝ Հուդա Իսկարիովտացին, որ նրան մատնելու էր, ասաց.","5":"«Ինչո՞ւ այդ յուղը երեք հարյուր դինարի չվաճառվեց ու աղքատներին չտրվեց»։","6":"Բայց նա այդ ասաց, ոչ թե որովհետև աղքատների մասին էր հոգում, այլ որովհետև գող էր և ընդհանուր գանձանակը տնօրինողն էր, և ինչ որ այնտեղ դրվում էր, իրեն էր պահում։","7":"Այդժամ Հիսուսն ասաց. «Թո՛ղ նրան. այն, ինչ նա անում է, իմ թաղման օրվա համար է։","8":"Աղքատներին միշտ ունեք ձեզ հետ, բայց ինձ միշտ չեք ունենալու»։","9":"Երբ հրեաներից շատերն իմացան, որ Հիսուսն այնտեղ է, եկան տեսնելու ոչ միայն նրան, այլ նաև Ղազարոսին, որին մեռելներից հարություն էր տվել։","10":"Իսկ քահանայապետները որոշեցին Ղազարոսին էլ սպանել,","11":"քանի որ նրա պատճառով հրեաներից շատերն էին գնում և Հիսուսին հավատում։","12":"Հաջորդ օրը, երբ Զատկի տոնին եկած ժողովրդի բազմությունը լսեց, որ Հիսուսը Երուսաղեմ է գալիս,","13":"արմավենու ճյուղեր վերցրեց և նրան ընդառաջ ելավ՝ աղաղակելով. «Օվսաննա՜ (եբր. Սաղ. 118.25), օրհնյա՜լ է նա, որ գալիս է Տիրոջ անունով (Սաղ. 118.26), Իսրայելի թագավորը»։","14":"Հիսուսը մի ավանակ գտավ և վրան նստեց, ինչպես որ գրված է.","15":"«Մի՛ վախեցիր, ո՛վ դուստր Սիոնի, ահա քո թագավորը գալիս է՝ էշի քուռակի վրա նստած» (Զաք. 9.9)։","16":"Նրա աշակերտներն սկզբում այս չհասկացան. բայց երբ Հիսուսը փառավորվեց, այն ժամանակ հիշեցին, որ դա նրա մասին էր գրված, և նրանք դա Հիսուսի համար արեցին։","17":"Եվ ժողովուրդը, որ նրա հետ էր, երբ Ղազարոսին գերեզմանից դուրս կանչեց ու նրան մեռելներից հարություն տվեց, պատմում էր այն, ինչ տեսել էր։","18":"Եվ դրա համար էր ժողովուրդը նրան ընդառաջ ելել, քանի որ լսել էր նրա գործած այդ նշանի մասին։","19":"Իսկ փարիսեցիները միմյանց ասում էին. «Տեսնո՞ւմ եք, որ ոչ մի օգուտ չունեք. ահավասիկ ողջ աշխարհը նրա հետևից է գնում»։","20":"Երուսաղեմ բարձրացածների մեջ կային որոշ հույներ, որոնք եկել էին տոնին՝ երկրպագություն անելու։","21":"Նրանք եկան Փիլիպպոսի մոտ, որը Գալիլեայի Բեթսայիդա քաղաքից էր. խնդրում էին նրան և ասում. «Տե՛ր, ուզում ենք Հիսուսին տեսնել»։","22":"Փիլիպպոսը եկավ և Անդրեասին ասաց, ապա Անդրեասն ու Փիլիպպոսն ասացին Հիսուսին։","23":"Իսկ Հիսուսը նրանց ասաց. «Ժամը հասավ, որ Մարդու Որդին փառավորվի։","24":"Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. եթե ցորենի հատիկը հողի մեջ ընկնի ու չմեռնի, միայն հատիկն ինքը կմնա, իսկ եթե մեռնի, շատ արդյունք կտա։","25":"Ով սիրում է իր անձը, կորցնելու է այն, իսկ ով այս աշխարհում իր անձն ատում է, հավիտենական կյանքի համար է պահելու այն։","26":"Եթե մեկը ծառայում է ինձ, թող գա իմ հետևից, և որտեղ ես եմ, իմ ծառան ևս այնտեղ կլինի։ Եթե մեկն ինձ ծառայի, նրան կպատվի Հայրը։","27":"Այժմ հոգիս խռովված է։ Ի՞նչ ասեմ. Հա՛յր, փրկի՛ր ինձ այս ժամից։ Բայց ես հենց դրա համար եմ եկել։","28":"Հա՛յր, փառավորի՛ր քո անունը»։ Այդժամ երկնքից ձայն եկավ. «Փառավորեցի և դարձյալ կփառավորեմ»։","29":"Ժողովուրդը, որ կանգնած էր ու լսում էր, ասում էր. «Որոտմունք եղավ»։ Ուրիշներն ասում էին. «Նրա հետ հրեշտակ խոսեց»։","30":"Հիսուսը պատասխանեց ու ասաց. «Այս ձայնը ինձ համար չեղավ, այլ ձեզ համար։","31":"Հիմա է այս աշխարհի դատաստանը, հիմա այս աշխարհի իշխանը դուրս է նետվելու։","32":"Եվ երբ ես բարձրանամ երկրից, բոլորին ինձ մոտ եմ ձգելու»։","33":"Եվ այս ասում էր, որպեսզի ցույց տար, թե ինչպիսի՛ մահով էր մեռնելու։","34":"Արդ ժողովուրդը նրան պատասխանեց. «Մենք օրենքից լսել ենք, որ Քրիստոսը պիտի մնա հավիտյան, իսկ դու ինչպե՞ս ես ասում, որ Մարդու Որդին պետք է բարձրանա. ո՞վ է այդ Մարդու Որդին»։","35":"Այդժամ Հիսուսը նրանց ասաց. «Մի փոքր ժամանակ դեռ լույսը ձեր մեջ է. քայլե՛ք, քանի դեռ լույսն ունեք, որպեսզի խավարը ձեզ չտիրի։ Ով քայլում է խավարում, նա չի իմանում, թե ո՛ւր է գնում։","36":"Քանի դեռ լույսն ունեք, հավատացե՛ք լույսին, որպեսզի լույսի որդիներ լինեք»։ Հիսուսն այս ասաց ու գնաց, նրանցից թաքնվեց։","37":"Եվ չնայած նա այդքան նշաններ էր արել նրանց առաջ, նրանք չէին հավատում նրան,","38":"որպեսզի իրականանար Եսայի մարգարեի միջոցով ասված խոսքը. «Տե՛ր, ո՞վ հավատաց մեր տված լուրին, և Տիրոջ բազուկն ո՞ւմ հայտնվեց» (Ես. 53.1)։","39":"Եսային ասել է նաև, թե նրանք ինչու չեն կարողանում հավատալ.","40":"«Նրանց աչքերը կուրացրեց և նրանց սրտերը անզգայացրեց, որ աչքերով չտեսնեն ու սրտով չիմանան, որ դարձի գան, և ե՛ս նրանց բուժեմ» (հմմտ. Ես. 6.10)։","41":"Եսային Հիսուսի մասին այս ասաց, երբ տեսնում էր նրա փառքը ու խոսում էր նրա մասին։","42":"Այնուամենայնիվ, իշխանավորներից շատերը նույնպես նրան հավատացին, սակայն փարիսեցիների պատճառով չէին խոստովանում, որպեսզի ժողովարանից չարտաքսվեն.","43":"քանի որ մարդկային փառքը գերադասեցին աստվածայինից։","44":"Հիսուսն աղաղակում էր ու ասում. «Ով հավատում է ինձ, միայն ինձ չէ, որ հավատում է, այլ նաև նրան, ով ինձ ուղարկեց։","45":"Եվ ով տեսնում է ինձ, տեսնում է նաև նրան, ով ինձ ուղարկեց։","46":"Ես իբրև լույս եկա աշխարհ, որպեսզի ամեն ոք, ով ինձ հավատում է, խավարի մեջ չմնա։","47":"Եվ եթե որևէ մեկն իմ խոսքերը լսի ու չպահի, ես նրան չեմ դատի, որովհետև ես չեկա աշխարհը դատելու, այլ փրկելու աշխարհը։","48":"Ով ինձ անարգի ու իմ խոսքերը չընդունի, կա մեկը, որ նրան կդատի. այն խոսքը, որ ես խոսեցի, դա է դատելու նրան վերջին օրը։","49":"Որովհետև ես ինքս ինձնից չեմ խոսել, այլ Հայրը, որ ինձ ուղարկեց, նա՛ է ինձ պատվիրել, թե ի՛նչ պետք է ասեմ և ի՛նչ պետք է խոսեմ։","50":"Եվ գիտեմ, որ նրա պատվիրանը հավիտենական կյանք է։ Արդ, ինչ որ ես խոսում եմ, այնպես եմ խոսում, ինչպես Հայրն ինձ ասաց»։"},"13":{"1":"Հիսուսը, Զատկի տոնից առաջ իմանալով, որ հասել է իր ժամը այս աշխարհից Հոր մոտ փոխադրվելու, մինչև վերջ ցույց տվեց իր սերը նրանց հանդեպ, ովքեր այս աշխարհում են։","2":"Եվ ընթրիքին սատանան արդեն Սիմոնի որդի Հուդա Իսկարիովտացու սրտի մեջ դրել էր, որ Հիսուսին մատնի։","3":"Հիսուսը գիտեր, որ Հայրն ամեն ինչ իր ձեռքն էր հանձնել, և որ ինքն Աստծուց էր ելել ու Աստծու մոտ էր գնում։","4":"Նա ընթրիքի սեղանից վեր կացավ, զգեստը հանեց ու մի սրբիչ վերցնելով՝ մեջքին կապեց։","5":"Ապա կոնքի մեջ ջուր լցրեց ու սկսեց աշակերտների ոտքերը լվանալ և մեջքին կապած սրբիչով սրբել։","6":"Երբ Սիմոն Պետրոսին հասավ, նա ասաց Հիսուսին. «Տե՛ր, դո՞ւ ես իմ ոտքերը լվանում»։","7":"Հիսուսը պատասխանեց նրան ու ասաց. «Այն, ինչ ես անում եմ, դու հիմա չես հասկանա, բայց այն հետո կհասկանաս»։","8":"Պետրոսը նրան ասաց. «Դու իմ ոտքերը երբեք չես լվանա»։ Հիսուսը նրան պատասխանեց. «Եթե քեզ չլվանամ, ինձ հետ բաժին չես ունենա»։","9":"Սիմոն Պետրոսը նրան ասաց. «Տե՛ր, ոչ միայն ոտքերս, այլ ձեռքերս ու գլուխս և՛ս լվա»։","10":"Հիսուսը նրան ասաց. «Ով լվացվել է, ամբողջովին մաքուր է և կարիք չունի ոչնչի, բացի ոտքերը լվանալուց. դուք էլ մաքուր եք, բայց ոչ բոլորդ»։","11":"Քանի որ նա գիտեր իրեն մատնողին, դրա համար ասաց. «Ոչ բոլորդ եք մաքուր»։","12":"Երբ նրանց ոտքերը լվաց, հագավ իր զգեստը ու դարձյալ սեղան նստեց։ Եվ նրանց ասաց. «Գիտե՞ք՝ ի՛նչ արեցի ձեզ։","13":"Դուք ինձ \"Վարդապետ\" և \"Տեր\" եք կոչում և ճիշտ եք ասում, որովհետև ե՛մ։","14":"Արդ եթե ես՝ Տերս ու Վարդապետս, լվացի ձեր ոտքերը, դուք նույնպես պարտավոր եք միմյանց ոտքերը լվանալ։","15":"Քանի որ ես ձեզ օրինակ ծառայեցի, որպեսզի ինչպես ես ձեզ արեցի, դուք էլ նույն կերպ անեք։","16":"Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. ծառան ավելի մեծ չէ, քան իր տերը, ոչ էլ ուղարկվածն է ավելի մեծ, քան իրեն ուղարկողը։","17":"Եթե այս բաներն իմացաք, երանելի կլինեք, թե որ դրանք կատարեք։","18":"Ձեր բոլորի համար չեմ ասում այդ. ես գիտեմ նրանց, որոնց ընտրել եմ։ Սակայն պետք է կատարվի գրվածը, որ ասում է. \"Ով ինձ հետ հաց էր ուտում, իմ դեմ դարձավ\" (Սաղ. 41.9).","19":"ես ձեզ այդ ասում եմ այժմվանից՝ մինչև դրա լինելը, որպեսզի երբ լինի, հավատաք, որ ես եմ։","20":"Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. ով ընդունում է նրան, ում ես ուղարկում եմ, ինձ է ընդունում, իսկ ով ինձ է ընդունում, ընդունում է ինձ ուղարկողին»։","21":"Երբ Հիսուսն այս բաներն ասաց, հոգով խռովվեց, վկայեց ու ասաց. «Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, որ ձեզանից մեկն ինձ մատնելու է»։","22":"Աշակերտները տարակուսանքով միմյանց էին նայում, թե ո՛ւմ մասին է ասում։","23":"Եվ աշակերտներից մեկը, որին Հիսուսը սիրում էր, նրա կողքին էր նստած։","24":"Սիմոն Պետրոսը նրան նշան արեց, որ հարցնի, թե ո՛ւմ մասին է ասում։","25":"Այդժամ նա հենվեց Հիսուսի կրծքին և նրան հարցրեց. «Տե՛ր, ո՞վ է նա»։","26":"Հիսուսը պատասխանեց. «Նա է, ում համար հացը կթրջեմ ու կտամ նրան»։ Արդ նա հացը թրջեց ու տվեց Սիմոնի որդի Հուդա Իսկարիովտացուն։","27":"Հացը վերցնելուց հետո սատանան մտավ նրա մեջ։ Հիսուսը նրան ասաց. «Ինչ որ անելու ես, արա՛գ արա»։","28":"Եվ սեղան նստածներից ոչ ոք չհասկացավ, թե ինչի՛ համար այդ ասաց նրան։","29":"Քանի որ Հուդան էր գանձանակը պահում, ոմանք կարծում էին, թե Հիսուսը նրան ասաց. «Գնի՛ր, ինչ որ այս տոնի համար մեզ հարկավոր է» կամ «Աղքատներին ինչ-որ բա՛ն տար»։","30":"Իսկ նա, երբ հացը վերցրեց, իսկույն դուրս գնաց։ Գիշեր էր։","31":"Երբ նա գնաց, Հիսուսն ասաց. «Այժմ Մարդու Որդին պիտի փառավորվի, Աստված էլ նրանով պիտի փառավորվի։","32":"Եթե Աստված նրանով փառավորվի, Աստված էլ նրան իրենով կփառավորի. և նրան իսկույն կփառավորի։","33":"Որդյակնե՛րս, դեռ մի փոքր ժամանակ ևս ձեզ հետ եմ. ինձ կփնտրեք, և ինչպես հրեաներին ասացի՝ \"Ուր ես եմ գնում, դուք չեք կարող գալ\", հիմա էլ ձեզ եմ ասում։","34":"Ձեզ նոր պատվիրան եմ տալիս, որ սիրեք միմյանց. ինչպես ես ձեզ սիրեցի, նույնպես դո՛ւք միմյանց սիրեք։","35":"Դրանով բոլորը կճանաչեն, որ դուք իմ աշակերտներն եք, եթե միմյանց նկատմամբ սեր ունենաք»։","36":"Սիմոն Պետրոսը նրան ասաց. «Տե՛ր, ո՞ւր ես գնում»։ Հիսուսը նրան պատասխանեց. «Ուր ես գնում եմ, դու հիմա իմ հետևից չես կարող գալ, բայց հետո իմ հետևից կգաս»։","37":"Պետրոսն ասաց նրան. «Տե՛ր, ինչո՞ւ չեմ կարող հիմա քո հետևից գալ. ես իմ կյանքը կտամ քեզ համար»։","38":"Հիսուսը նրան պատասխանեց. «Ինձ համար կյա՞նքդ կտաս. ճշմարիտ, ճշմարիտ եմ ասում քեզ. աքաղաղը դեռ չկանչած՝ դու ինձ երեք անգամ կուրանաս»։"},"14":{"1":"«Ձեր սրտերը թող չխռովվեն. հավատացե՛ք Աստծուն, հավատացե՛ք նաև ինձ։","2":"Իմ Հոր տանը բազում օթևաններ կան։ Եթե ոչ, ես ձեզ կասեի։ Ես գնում եմ ձեզ համար տեղ պատրաստելու։","3":"Եվ երբ գնամ ու ձեզ համար տեղ պատրաստեմ, վերստին կգամ ու ձեզ ինձ մոտ կվերցնեմ, որպեսզի որտեղ ես եմ, դուք էլ լինեք։","4":"Եվ ուր ես գնում եմ, գիտեք, գիտեք նաև ճանապարհը»։","5":"Թովմասը նրան ասաց. «Տե՛ր, մենք չգիտենք, թե ո՛ւր ես գնում, արդ ճանապարհն ինչպե՞ս կարող ենք իմանալ»։","6":"Հիսուսը նրան ասաց. «Ես եմ ճանապարհը, ճշմարտությունն ու կյանքը. ոչ ոք Հոր մոտ չի գա, եթե ոչ իմ միջոցով։","7":"Եթե ինձ ճանաչեիք, իմ Հորն էլ ճանաչած կլինեիք։ Բայց այսուհետև ճանաչեցիք նրան և տեսաք»։","8":"Փիլիպպոսը նրան ասաց. «Տե՛ր, ցո՛ւյց տուր մեզ Հորը, և դա մեզ բավական է»։","9":"Հիսուսը նրան ասաց. «Այսքան ժամանակ ձեզ հետ եմ, և ինձ չճանաչեցի՞ր, Փիլիպպո՛ս։ Ով ինձ տեսավ, նա Հորը տեսավ. իսկ դու ինչպե՞ս ես ասում. \"Ցո՛ւյց տուր մեզ Հորը\"։","10":"Չե՞ս հավատում, որ ես Հոր մեջ եմ, և Հայրն էլ իմ մեջ է։ Այն խոսքերը, որ ես ձեզ ասում եմ, ինքս ինձնից չեմ ասում, այլ Հայրը, որ իմ մեջ է, նա է գործերը կատարում։","11":"Հավատացե՛ք ինձ, որ ես Հոր մեջ եմ, և Հայրն էլ իմ մեջ է. եթե ոչ, գոնե գործերի համա՛ր հավատացեք ինձ։","12":"Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. ով հավատում է ինձ, ինքն էլ նույն գործերը կանի, որ ես եմ անում, և դրանցից է՛լ ավելի մեծ բաներ կանի, որովհետև ես իմ Հոր մոտ եմ գնում։","13":"Եվ ինչ որ իմ անունով խնդրեք, կանեմ, որպեսզի Հայրը Որդու միջոցով փառավորվի։","14":"Եթե իմ անունով որևէ բան խնդրեք, ես այն կկատարեմ։","15":"Եթե ինձ սիրում եք, պահե՛ք իմ պատվիրանները։","16":"Եվ ես Հորը կխնդրեմ, և ձեզ ուրիշ Մխիթարիչ կտա, որպեսզի հավիտյան ձեզ հետ լինի.","17":"ճշմարտության Հոգին, որին աշխարհը չի կարող ընդունել, որովհետև նրան չի տեսնում և չի ճանաչում։ Բայց դուք նրան ճանաչում եք, որովհետև այն ձեզ մոտ է մնում ու ձեր մեջ է լինելու։","18":"Ես ձեզ որբ չեմ թողնի. կգամ ձեզ մոտ։","19":"Մի փոքր ժամանակ ևս, և աշխարհն այլևս ինձ չի տեսնի. բայց դուք ինձ կտեսնեք, որովհետև ես կենդանի եմ, և դուք նույնպես կենդանի եք լինելու։","20":"Այն օրը դուք կիմանաք, որ ես իմ Հոր մեջ եմ, և դուք՝ իմ մեջ, իսկ ես՝ ձեր մեջ։","21":"Ով ունի իմ պատվիրանները և պահում է դրանք, նա՛ է ինձ սիրում. ով ինձ սիրում է, պիտի սիրվի իմ Հորից, ես էլ պիտի սիրեմ նրան և ինձ պիտի հայտնեմ նրան»։","22":"Հուդան (ոչ Իսկարիովտացին) նրան ասաց. «Տե՛ր, ի՞նչ պատահեց, որ քեզ պիտի հայտնես մեզ, իսկ աշխարհին՝ ոչ»։","23":"Հիսուսը պատասխանեց ու ասաց նրան. «Եթե մեկն ինձ սիրում է, իմ խոսքը կպահի։ Եվ իմ Հայրը կսիրի նրան, և նրա մոտ կգանք ու բնակություն կհաստատենք նրա մոտ։","24":"Ով ինձ չի սիրում, իմ խոսքերը չի պահում. և այն խոսքը, որ լսում եք, իմը չէ, այլ Հորը, որ ինձ ուղարկեց։","25":"Այս բաները ձեզ ասացի, մինչ ձեզ մոտ եմ։","26":"Բայց Մխիթարիչը՝ Սուրբ Հոգին, որին Հայրն ուղարկելու է իմ անունով, նա ամեն բան ձեզ կուսուցանի ու կհիշեցնի ձեզ այն ամենը, ինչ ձեզ ասացի։","27":"Խաղաղություն եմ թողնում ձեզ, իմ խաղաղությունն եմ տալիս ձեզ. ես այն ձեզ չեմ տալիս, ինչպես աշխարհն է տալիս. ձեր սիրտը թող չխռովվի ու չվախենա։","28":"Լսեցիք, որ ձեզ ասացի. \"Գնում եմ, բայց գալու եմ ձեզ մոտ\"։ Եթե ինձ սիրեիք, ապա ուրախ կլինեիք, որ ասացի. \"Հոր մոտ եմ գնում\", որովհետև իմ Հայրն ավելի մեծ է, քան ես։","29":"Եվ ձեզ հիմա՛ ասացի՝ նախքան լինելը, որպեսզի երբ լինի, հավատաք։","30":"Ձեզ հետ այլևս շատ չեմ խոսի, որովհետև գալիս է այս աշխարհի իշխանը, և նա ինձ վրա ոչ մի իշխանություն չունի։","31":"Սակայն որպեսզի աշխարհն իմանա, որ ես սիրում եմ Հորը, անում եմ այնպես, ինչպես Հայրը պատվիրեց ինձ։ Վե՛ր կացեք գնանք այստեղից»։"},"15":{"1":"«Ես եմ ճշմարիտ որթատունկը, և իմ Հայրը մշակն է։","2":"Յուրաքանչյուր որթաճյուղ, որ ինձ վրա է և պտուղ չի տալիս, նա կտրում է այն. և յուրաքանչյուր պտղաբեր որթաճյուղ էտում է, որ առավել պտղաբեր լինի։","3":"Դուք արդեն մաքրվել եք այն խոսքի միջոցով, որ ձեզ ասացի։","4":"Մնացե՛ք իմ մեջ, ես էլ՝ ձեր մեջ։ Ինչպես որթաճյուղն ինքն իրենից չի կարող պտղաբերել, եթե որթատունկի հետ միավորված չլինի, այնպես էլ դուք, եթե ինձ հետ չմիավորվեք։","5":"Ես եմ որթատունկը, իսկ դուք՝ ճյուղերը. ով ինձ հետ է միավորվում, իսկ ես՝ նրա հետ, նա շատ պտուղ է տալիս, որովհետև առանց ինձ ոչինչ չեք կարող անել։","6":"Եթե մեկն ինձ հետ չի միավորվում, նրան որթաճյուղի պես կնետեն, և կչորանա։ Ապա այն կհավաքեն, կրակը կգցեն, և կայրվի։","7":"Եթե ինձ հետ միավորված մնաք, իմ խոսքերն էլ ձեր մեջ մնան, ինչ որ կամենաք, խնդրեք, այն ձեզ կտրվի։","8":"Իմ Հայրն այն դեպքում կփառավորվի, երբ դուք շատ պտուղ տաք և իմ աշակերտները լինեք։","9":"Ինչպես Հայրն ինձ սիրեց, այնպես էլ ես ձեզ սիրեցի. մնացե՛ք իմ սիրո մեջ։","10":"Եթե իմ պատվիրանները պահեք, կմնաք իմ սիրո մեջ, ինչպես ես իմ Հոր պատվիրանները պահեցի և նրա սիրո մեջ եմ մնում։","11":"Այս բաները ձեզ ասացի, որպեսզի իմ ուրախությունը ձեր մեջ լինի, և ձեր ուրախությունը կատարյալ լինի։","12":"Սա է իմ պատվիրանը, որ սիրեք միմյանց, ինչպես ես ձեզ սիրեցի։","13":"Ոչ ոք ավելի մեծ սեր չունի, քան նա, ով իր կյանքն է տալիս իր բարեկամների համար։","14":"Դուք իմ բարեկամներն եք, եթե անեք այն, ինչ ես պատվիրում եմ ձեզ։","15":"Ձեզ այլևս ծառաներ չեմ կոչում, որովհետև ծառան չգիտի, թե իր տերն ի՛նչ է անում։ Ձեզ բարեկամներ եմ կոչում, որովհետև այն ամենը, ինչ իմ Հորից լսեցի, ձեզ հայտնեցի։","16":"Դո՛ւք չէ, որ ինձ ընտրեցիք, այլ ե՛ս ձեզ ընտրեցի ու ձեզ կարգեցի, որպեսզի դուք գնաք և պտղաբերեք, ու ձեր պտուղը մնա. որպեսզի ինչ որ իմ անունով խնդրեք Հորից, տա ձեզ։","17":"Այս եմ ձեզ պատվիրում, որ սիրեք միմյանց։","18":"Եթե աշխարհը ձեզ ատում է, իմացե՛ք, որ նախ ինձ է ատել։","19":"Եթե այս աշխարհից լինեիք, ապա աշխարհը ձեզ իբրև յուրայինների կսիրեր. բայց քանի որ աշխարհից չեք, այլ ես ձեզ աշխարհից ընտրեցի, դրա համար աշխարհն ատում է ձեզ։","20":"Հիշե՛ք այն խոսքը, որ ես ձեզ ասացի. \"Ծառան ավելի մեծ չէ, քան իր տերը\"։ Եթե ինձ հալածեցին, ձեզ նույնպես հալածելու են. եթե իմ խոսքը պահեցին, ձերն էլ կպահեն։","21":"Բայց այս ամենը իմ անվան պատճառով կանեն ձեզ, որովհետև ինձ ուղարկողին չեն ճանաչում։","22":"Եթե ես եկած և նրանց հետ խոսած չլինեի, նրանք մեղք չէին ունենա. բայց հիմա իրենց մեղքի համար ոչ մի արդարացում չունեն։","23":"Ով ինձ ատում է, իմ Հորն էլ է ատում։","24":"Եթե նրանց մեջ կատարած չլինեի այն գործերը, որ ուրիշ ոչ ոք չէր կատարել, մեղք չէին ունենա։ Սակայն այժմ այդ գործերը տեսան ու ատեցին թե՛ ինձ, թե՛ իմ Հորը։","25":"Բայց դա տեղի ունեցավ, որպեսզի կատարվի նրանց օրենքում գրված խոսքը. \"Ինձ առանց պատճառի ատեցին\" (Սաղ. 35.19, 69.4)։","26":"Երբ Մխիթարիչը գա, որին ես Հոր կողմից կուղարկեմ ձեզ, ճշմարտության Հոգին, որ Հորից է ելնում, նա կվկայի իմ մասին։","27":"Եվ դուք էլ կվկայեք, որովհետև սկզբից ինձ հետ եք»։"},"16":{"1":"«Այս բաներն ասացի ձեզ, որպեսզի չգայթակղվեք։","2":"Ձեզ ժողովարաններից դուրս պիտի հանեն։ Նույնիսկ ժամանակ կգա, երբ ով ձեզ սպանի, պիտի համարի, թե պաշտամունք է մատուցում Աստծուն։","3":"Եվ դա պիտի ձեզ անեն, որովհետև ո՛չ Հորը ճանաչեցին, ո՛չ էլ ինձ։","4":"Բայց այս բաները ձեզ ասացի, որպեսզի երբ սրանց կատարվելու ժամանակը գա, հիշեք, որ ես այդ ասել եմ ձեզ։ Այս բաներն սկզբից ձեզ չասացի, քանի որ ձեզ հետ էի։","5":"Սակայն այժմ ինձ ուղարկողի մոտ եմ գնում, ու ձեզնից ոչ ոք ինձ չի հարցնում. \"Ո՞ւր ես գնում\"։","6":"Բայց որովհետև ձեզ այս բաներն ասացի, տրտմությունը լցրեց ձեր սիրտը։","7":"Բայց ես ձեզ ճշմարիտն եմ ասում. ձեզ համար ավելի լավ է, որ ես գնամ, որովհետև եթե ես չգնամ, Մխիթարիչը ձեզ մոտ չի գա. իսկ եթե գնամ, նրան ձեզ մոտ կուղարկեմ։","8":"Եվ երբ նա գա, աշխարհին կհանդիմանի մեղքի, արդարության և դատաստանի համար.","9":"մեղքի համար, որովհետև ինձ չեն հավատում,","10":"արդարության համար, որովհետև ես Հոր մոտ եմ գնում, ու ինձ այլևս չեք տեսնի,","11":"և դատաստանի համար, որովհետև այս աշխարհի իշխանը դատապարտված է։","12":"Դեռ շատ բան ունեմ ձեզ ասելու, բայց հիմա չեք կարող տանել։","13":"Սակայն երբ նա՝ ճշմարտության Հոգին, գա, ձեզ կառաջնորդի դեպի ամբողջ ճշմարտությունը, որովհետև ինքն իրենից չի խոսի, այլ կասի, ինչ որ լսի. և գալիք բաների մասին կպատմի ձեզ։","14":"Նա ինձ պիտի փառավորի, որովհետև վերցնելու է իմ ունեցածից ու հայտնելու է ձեզ։","15":"Այն ամենը, ինչ Հայրն ունի, իմն է. դրա համար ձեզ ասացի, թե ինչ որ ինձնից վերցնի, կհայտնի ձեզ։","16":"Մի քիչ ևս, և ինձ չեք տեսնի, և դարձյալ մի քիչ, ու ինձ կտեսնեք, որովհետև ես Հոր մոտ եմ գնում»։","17":"Նրա աշակերտներից ոմանք միմյանց ասում էին. «Այս ի՞նչ է մեզ ասում. \"Մի քիչ ևս, և ինձ չեք տեսնի, ու դարձյալ մի քիչ, և ինձ կտեսնեք\" և թե՝ \"Ես Հոր մոտ եմ գնում\"»։","18":"Նաև ասում էին. «Ի՞նչ է նշանակում, երբ ասում է՝ մի քիչ ևս։ Չենք հասկանում, թե ի՛նչ է խոսում»։","19":"Հիսուսը հասկացավ, որ ուզում են իրեն հարցնել, և նրանց ասաց. «Դրա՞ համար էիք միմյանց հարցնում, երբ ասացի. \"Մի քիչ ևս, և ինձ չեք տեսնի, և դարձյալ մի քիչ, և ինձ կտեսնեք\"։","20":"Ճշմարիտ, ճշմարիտ եմ ասում ձեզ, որ դուք պիտի լաք ու ողբաք, իսկ աշխարհը պիտի ուրախանա. դուք պիտի տրտմեք, բայց ձեր տրտմությունն ուրախության պիտի վերածվի։","21":"Երբ կինը ծննդաբերում է, տանջվում է, քանի որ նրա ժամը հասել է. բայց երբ երեխային ծնում է, ուրախության շնորհիվ նեղությունն այլևս չի հիշում, քանի որ աշխարհում մի մարդ էլ ծնվեց։","22":"Դուք նույնպես այժմ նեղություն եք կրում, բայց ես դարձյալ պիտի տեսնեմ ձեզ, ու ձեր սիրտը պիտի ուրախանա, և ձեր ուրախությունը ոչ ոք ձեզանից չի խլելու։","23":"Եվ այդ օրն ինձ ոչինչ չեք հարցնելու։ Ճշմարիտ, ճշմարիտ եմ ասում ձեզ. ինչ որ իմ անունով Հորից խնդրեք, կտա ձեզ։","24":"Մինչև հիմա իմ անունով ոչինչ չեք խնդրել. խնդրե՛ք և պիտի ստանաք, որպեսզի ձեր ուրախությունը կատարյալ լինի։","25":"Այս բաները ձեզ ասացի առակներով, բայց գալու է ժամանակ, երբ ձեզ հետ այլևս առակներով չեմ խոսելու, այլ Հոր մասին ձեզ հայտնապես եմ պատմելու։","26":"Այդ օրն իմ անունով պիտի խնդրեք։ Եվ չեմ ասում, թե ե՛ս ձեզ համար պիտի խնդրեմ Հորը,","27":"որովհետև Հայրն ինքը սիրում է ձեզ, քանի որ դուք ինձ սիրել եք ու հավատացել, որ ես Աստծուց եմ ելել։","28":"Ես ելա Հորից և եկա աշխարհ. դարձյալ թողնում եմ աշխարհը և գնում եմ Հոր մոտ»։","29":"Աշակերտները նրան ասացին. «Այժմ ահա բացահայտ ես խոսում և ոչ մի առակ չես ասում։","30":"Հիմա հասկանում ենք, որ դու ամեն ինչ գիտես ու կարիք չունես, որ որևէ մեկը քեզ բան հարցնի։ Սրանով հավատում ենք, որ դու Աստծուց ես ելել»։","31":"Հիսուսը նրանց պատասխանեց. «Հիմա հավատո՞ւմ եք։","32":"Ահա ժամանակը գալիս է, և արդեն իսկ եկել է, երբ բոլորդ կցրվեք, յուրաքանչյուրը՝ իր տունը, և ինձ մենակ կթողնեք։ Բայց ես մենակ չեմ, որովհետև Հայրն ինձ հետ է։","33":"Այս բաներն ասացի ձեզ, որպեսզի ինձնով խաղաղություն ունենաք։ Աշխարհում նեղություն պիտի ունենաք, բայց քաջալերվե՛ք, որովհետև ես հաղթել եմ աշխարհին"},"17":{"1":"Հիսուսն այս բաներն ասելուց հետո աչքերը դեպի երկինք բարձրացրեց ու ասաց. «Հա՛յր, ժամը հասել է. փառավորի՛ր քո Որդուն, որպեսզի քո Որդին էլ քեզ փառավորի։","2":"Ինչպես դու նրան իշխանություն տվեցիր բոլոր մարդկանց վրա, այնպես էլ նա հավիտենական կյանք կտա բոլոր նրանց, ովքեր նրան հավատացին։","3":"Այս է հավիտենական կյանքը, որ ճանաչեն քեզ իբրև միակ ճշմարիտ Աստծու և նրան, որին ուղարկել ես՝ Հիսուս Քրիստոսին։","4":"Ես քեզ երկրի վրա փառավորեցի. կատարեցի այն գործը, որն ինձ տվեցիր, որ անեմ։","5":"Իսկ հիմա, Հա՛յր, դո՛ւ ինձ փառավորիր քո ունեցած այն փառքով, որ ունեի քեզ մոտ նախքան աշխարհի ստեղծումը։","6":"Քո անունը հայտնեցի այն մարդկանց, որոնց ինձ տվեցիր այս աշխարհից։ Նրանք քոնն էին, ու ինձ տվեցիր նրանց, և քո խոսքը պահեցին։","7":"Հիմա նրանք գիտեն, որ այն ամենը, ինչ ինձ տվեցիր, քեզանից է,","8":"որովհետև այն խոսքը, որ ինձ տվեցիր, ես նրանց տվեցի։ Նրանք այն ընդունեցին ու ճանաչեցին, որ իրապես ես քեզանից ելա, ու հավատացին, որ դո՛ւ ինձ ուղարկեցիր։","9":"Ես նրանց համար եմ խնդրում և ոչ աշխարհի, նրանց համար, որոնց ինձ տվեցիր, որովհետև նրանք քոնն են։","10":"Եվ այն ամենը, ինչ իմն է, քոնն է, և ինչ որ քոնն է, իմն է. ու ես նրանցով փառավորված եմ։","11":"Ես այլևս աշխարհի մեջ չեմ, իսկ նրանք այս աշխարհի մեջ են. և ես քեզ մոտ եմ գալիս։ Սո՛ւրբ Հայր, պահի՛ր նրանց քո անունով, որ ինձ տվեցիր, որպեսզի միավորված լինեն, ինչպես որ մենք ենք միավորված։","12":"Երբ ես աշխարհում նրանց հետ էի, ես նրանց պահում էի քո անունով, որն ինձ տվեցիր։ Ես պահեցի, ու նրանցից ոչ մեկը չկորավ, բացի կորստյան որդուց, որպեսզի իրականանար գրվածը։","13":"Բայց հիմա ես քեզ մոտ եմ գալիս և այս բաներն ասում եմ, ինչքան ժամանակ որ աշխարհում եմ, որպեսզի իմ ուրախությունն իրենց մեջ ամենայն կատարելությամբ ունենան։","14":"Ես քո խոսքը նրանց տվեցի, սակայն աշխարհը նրանց ատեց, որովհետև նրանք այս աշխարհից չեն, ինչպես որ ես այս աշխարհից չեմ։","15":"Ես չեմ խնդրում, որ նրանց աշխարհից վերցնես, այլ որ նրանց պահես չարից։","16":"Նրանք այս աշխարհից չեն, ինչպես որ ես այս աշխարհից չեմ։","17":"Սրբացրո՛ւ նրանց քո ճշմարտությամբ. քո խոսքը ճշմարտություն է։","18":"Ինչպես դու ինձ աշխարհ ուղարկեցիր, այնպես էլ ես նրանց աշխարհ ուղարկեցի։","19":"Եվ ես ինձ նրանց համար եմ սրբացնում, որպեսզի նրանք էլ սրբացվեն ճշմարտությամբ։","20":"Բայց միայն նրանց համար չեմ խնդրում, այլ նաև նրանց, ովքեր նրանց խոսքի միջոցով կհավատան ինձ,","21":"որպեսզի բոլորը մեկ լինեն, ինչպես դու, Հա՛յր, իմ մեջ, և ես՝ քո մեջ. որպեսզի նրանք էլ մեր մեջ լինեն, որպեսզի աշխարհը հավատա, որ դո՛ւ ինձ ուղարկեցիր։","22":"Եվ այն փառքը, որ ինձ տվեցիր, ես նրանց տվեցի, որպեսզի մեկ լինեն, ինչպես մենք ենք մեկ։","23":"Ես՝ նրանց մեջ, և դու՝ իմ մեջ, որպեսզի կատարյալ լինեն միության մեջ, որպեսզի աշխարհն իմանա, որ դո՛ւ ինձ ուղարկեցիր ու նրանց սիրեցիր այնպես, ինչպես ինձ սիրեցիր։","24":"Հա՛յր, ում ինձ տվեցիր, ուզում եմ, որ ինձ հետ լինեն, որտեղ ես եմ, որպեսզի իմ փառքը տեսնեն. այն փառքը, որ ինձ տվեցիր. որովհետև ինձ սիրեցիր նախքան աշխարհը ստեղծելը։","25":"Արդա՛ր Հայր, աշխարհը քեզ չճանաչեց, բայց ես քեզ ճանաչեցի, և նրանք իմացան, որ դո՛ւ ինձ ուղարկեցիր։","26":"Եվ ես քո անունը նրանց ճանաչել տվեցի ու պիտի ճանաչել տամ, որպեսզի այն սերը, որով ինձ սիրեցիր, նրանց մեջ լինի, և ես՝ նրանց մեջ»։"},"18":{"1":"Հիսուսն այս ասելուց հետո իր աշակերտների հետ ելավ գնաց Կեդրոնի ձորի մյուս կողմը։ Այնտեղ մի պարտեզ կար, ուր մտան ինքն ու իր աշակերտները։","2":"Հուդան՝ Հիսուսին մատնողը, նույնպես գիտեր այդ տեղը, որովհետև Հիսուսն ու իր աշակերտները շատ անգամ էին այդտեղ հավաքվել։","3":"Եվ Հուդան, իր հետ վերցնելով զինվորների գունդն ու տաճարի պահակներին, որոնց իրեն տվել էին քահանայապետներն ու փարիսեցիները, ջահերով, լապտերներով ու զենքերով եկավ այնտեղ։","4":"Արդ Հիսուսը, իրեն սպասվող այս ամենն իմանալով, գնաց և նրանց հարցրեց. «Ու՞մ եք փնտրում»։","5":"Նրան պատասխանեցին. «Հիսուս Նազովրեցուն»։ Հիսուսը նրանց ասաց. «Ես եմ»։ Նրանց հետ էր նաև Հուդան՝ նրան մատնողը։","6":"Հենց որ նրանց ասաց՝ «Ես եմ», նրանք հետ-հետ գնացին ու ընկան գետնին։","7":"Եվ դարձյալ նրանց հարցրեց. «Ո՞ւմ եք փնտրում»։ Նրանք ասացին. «Հիսուս Նազովրեցուն»։","8":"Հիսուսը պատասխանեց. «Ձեզ ասացի՝ \"Ես եմ\". արդ, եթե ինձ եք փնտրում, թո՛ւյլ տվեք նրանց, որ գնան։","9":"Որպեսզի կատարվի այն խոսքը, որ ասում էր. \"Նրանց, ում տվեցիր ինձ, նրանցից և ոչ մեկին չկորցրի\"»։","10":"Իսկ Սիմոն Պետրոսը, որ սուր ուներ, քաշեց այն, քահանայապետի ծառային խփեց և նրա աջ ականջը կտրեց։ Ծառայի անունը Մաղքոս էր։","11":"Հիսուսը Պետրոսին ասաց. «Սուրդ պատյանի մե՛ջ դիր. մի՞թե չպիտի խմեմ բաժակը, որ Հայրն ինձ տվեց»։","12":"Այդժամ զինվորների գունդը, հազարապետն ու հրեա պահակները բռնեցին Հիսուսին ու կապեցին։","13":"Նրան նախ բերեցին Աննասի մոտ, որը Կայիափայի՝ այդ տարվա քահանայապետի աներն էր։","14":"Սա այն Կայիափան էր, որ հրեաներին խորհուրդ տվեց, թե ավելի լավ է՝ ժողովրդի համար մեկ մարդ մեռնի։","15":"Հիսուսի հետևից գնում էին Սիմոն Պետրոսն ու մյուս աշակերտը։ Այդ աշակերտը քահանայապետին ծանոթ էր, ուստի Հիսուսի հետ մտավ քահանայապետի գավիթը։","16":"Իսկ Պետրոսը կանգնել էր դրսում՝ դռան մոտ։ Այդ ժամանակ մյուս աշակերտը, որ քահանայապետին ծանոթ էր, դուրս ելավ, դռնապանի հետ խոսեց և Պետրոսին ներս մտցրեց։","17":"Եվ դռնապան աղջիկը Պետրոսին ասաց. «Գուցե դու է՞լ ես այն մարդու աշակերտներից»։ Եվ նա ասաց. «Ո՛չ, չեմ»։","18":"Այնտեղ կանգնած էին նաև ծառաներ ու պահակներ, որոնք կրակ էին վառել ու տաքանում էին, քանի որ ցուրտ էր։ Պետրոսը ևս նրանց հետ կանգնել ու տաքանում էր։","19":"Եվ քահանայապետը Հիսուսին հարցրեց նրա աշակերտների և ուսուցումների մասին։","20":"Հիսուսը նրան պատասխանեց. «Ես բացահայտ խոսեցի աշխարհում. ես միշտ ուսուցանել եմ ժողովարանում և տաճարում, որտեղ հավաքվում էին հրեաները։ Ես ոչինչ ծածուկ չեմ խոսել։","21":"Ինչո՞ւ ես ինձ հարցնում. հարցրո՛ւ լսողներին, թե ի՛նչ եմ նրանց հետ խոսել։ Ահավասիկ նրանք գիտեն՝ ես ի՛նչ եմ ասել»։","22":"Երբ Հիսուսն այս ասաց, այնտեղ կանգնած պահակներից մեկը նրան ապտակեց ու ասաց. «Այդպե՞ս ես պատասխանում քահանայապետին»։","23":"Հիսուսը նրան պատասխանեց. «Եթե որևէ վատ բան ասացի, վկայի՛ր վատի մասին, բայց եթե ես ճիշտն ասացի, ինչո՞ւ ես ինձ խփում»։","24":"Այդժամ Աննասը նրան կապված ուղարկեց Կայիափա քահանայապետի մոտ։","25":"Այնտեղ, որտեղ Սիմոն Պետրոսը կանգնել և տաքանում էր, նրան ասացին. «Գուցե դու է՞լ ես նրա աշակերտներից»։ Նա ուրացավ և ասաց. «Ո՛չ, չեմ»։","26":"Եվ քահանայապետի ծառաներից մեկը, որ ազգականն էր նրա, ում ականջը Պետրոսը կտրել էր, ասաց. «Չէ՞ որ ես ինքս քեզ տեսա այն պարտեզում նրա հետ»։","27":"Պետրոսը դարձյալ ուրացավ, և իսկույն աքաղաղը կանչեց։","28":"Հիսուսին Կայիափայի մոտից տարան ատյան։ Վաղ առավոտ էր։ Նրանք ատյան չմտան, որպեսզի չպղծվեն, այլ որպեսզի զատիկն ուտեն։","29":"Պիղատոսը դուրս ելավ նրանց մոտ և ասաց. «Այդ մարդու դեմ ի՞նչ մեղադրանք եք առաջադրում»։","30":"Նրան պատասխանեցին. «Եթե նա չարագործ չլիներ, ապա նրան քեզ չէինք մատնի»։","31":"Այդժամ Պիղատոսը նրանց ասաց. «Նրան դո՛ւք վերցրեք ու ձեր օրենքի համաձա՛յն դատեք»։ Հրեաները նրան ասացին. «Մեզ չի թույլատրվում որևէ մեկին մահապատժի ենթարկել».","32":"որպեսզի կատարվեր Հիսուսի այն խոսքը, որ ասաց՝ ցույց տալով, թե ինքն ի՛նչ մահով է մեռնելու։","33":"Պիղատոսը դարձյալ ատյան մտավ, կանչեց Հիսուսին ու հարցրեց նրան. «Դո՞ւ ես հրեաների թագավորը»։","34":"Հիսուսը պատասխանեց. «Դու այդ ի՞նքդ ես հարցնում, թե՞ քեզ ուրիշներն են իմ մասին ասել»։","35":"Պիղատոսը պատասխանեց. «Մի՞թե ես էլ հրեա եմ։ Քո ազգն ու քահանայապետները քեզ մատնեցին ինձ։ Ուրեմն ի՞նչ ես արել»։","36":"Հիսուսը պատասխանեց. «Իմ թագավորությունն այս աշխարհից չէ։ Եթե իմ թագավորությունն այս աշխարհից լիներ, ապա իմ հետևորդները կպայքարեին, որ ես հրեաների ձեռքը չմատնվեի. ուստի և իմ թագավորությունն այստեղից չէ»։","37":"Արդ, Պիղատոսը նրան ասաց. «Ուրեմն դու թագավո՞ր ես»։ Հիսուսը պատասխանեց. «Դո՛ւ ես ասում, որ թագավոր եմ։ Ես ծնվել ու աշխարհ եմ եկել, որպեսզի ճշմարտության մասին վկայեմ։ Ամեն ոք, ով ճշմարտությունից է, իմ ձայնը լսում է»։","38":"Պիղատոսը նրան ասաց. «Ի՞նչ է ճշմարտությունը»։ Եվ այս ասելուց հետո դարձյալ դուրս գնաց հրեաների մոտ ու նրանց ասաց. «Ես նրա մեջ ոչ մի հանցանք չեմ գտնում։","39":"Բայց ձեր մեջ կա մի սովորույթ, որ Զատկին ձեզ համար մի բանտարկյալ պիտի արձակեմ։ Արդ ուզո՞ւմ եք, որ ձեզ համար հրեաների թագավորին արձակեմ»։","40":"Սակայն բոլորն աղաղակեցին և ասացին. «Ո՛չ դրան, այլ Բարաբբային»։ Իսկ այդ Բարաբբան մի ավազակ էր։"},"19":{"1":"Այդ ժամանակ Պիղատոսը հրամայեց վերցնել ու գանահարել Հիսուսին։","2":"Զինվորները փշերից պսակ հյուսեցին, նրա գլխին դրեցին ու ծիրանի հագցրին։","3":"Գալիս էին նրա մոտ ու ասում. «Ողջո՜ւյն, հրեաների՛ թագավոր»։ Եվ ապտակում էին նրան։","4":"Պիղատոսը դարձյալ դուրս ելավ ու նրանց ասաց. «Ահա նրան դուրս եմ բերում, որպեսզի իմանաք, որ ես նրա մեջ ոչ մի հանցանք չեմ գտնում»։","5":"Արդ Հիսուսը դուրս ելավ՝ փշե պսակը գլխին և ծիրանին հագին։ Եվ Պիղատոսը նրանց ասաց. «Ահա այդ մարդը»։","6":"Երբ քահանայապետներն ու պահակները նրան տեսան, աղաղակեցին ու ասացին. «Խա՛չը հանիր, խա՛չը հանիր դրան»։ Պիղատոսը նրանց ասաց. «Դո՛ւք վերցրեք նրան ու խաչը հանեք, որովհետև ես նրա մեջ հանցանք չեմ գտնում»։","7":"Հրեաները նրան պատասխանեցին. «Մենք օրենք ունենք, և համաձայն մեր օրենքի՝ նա պետք է մեռնի, որովհետև իրեն Աստծու Որդի դարձրեց»։","8":"Երբ Պիղատոսն այս խոսքը լսեց, է՛լ ավելի վախեցավ։","9":"Նա դարձյալ ատյան մտավ և Հիսուսին ասաց. «Դու որտեղի՞ց ես»։ Բայց Հիսուսը նրան չպատասխանեց։","10":"Արդ Պիղատոսը նրան ասաց. «Ինձ հետ չե՞ս խոսում. չգիտե՞ս, որ իշխանություն ունեմ քեզ խաչը հանելու և իշխանություն ունեմ քեզ ազատ արձակելու»։","11":"Հիսուսը պատասխանեց. «Դու ինձ վրա ոչ մի իշխանություն էլ չէիր ունենա, եթե այն քեզ վերուստ տրված չլիներ։ Դրա համար նա, ով ինձ քո ձեռքը մատնեց, ավելի մեծ մեղք գործեց»։","12":"Եվ դրանից հետո Պիղատոսն ուզում էր նրան ազատ արձակել, բայց հրեաներն աղաղակում էին և ասում. «Եթե նրան ազատ արձակես, կայսրի բարեկամը չես։ Ով իրեն թագավոր է համարում, հակառակ է կայսրին»։","13":"Երբ Պիղատոսն այս խոսքերը լսեց, Հիսուսին դուրս բերեց, և ինքը նստեց բեմի վրա՝ այնտեղ, որ «Քարահատակ» էր կոչվում (եբրայերեն՝ Գաբբաթա)։","14":"Զատկի նախօրեն էր՝ մոտավորապես վեցերորդ ժամը։ Եվ նա հրեաներին ասաց. «Ահա ձեր թագավորը»։","15":"Իսկ նրանք աղաղակում էին. «Վերցրո՛ւ, վերցրո՛ւ և խա՛չը հանիր դրան»։ Պիղատոսը նրանց ասաց. «Ձեր թագավորին խա՞չը հանեմ»։ Քահանայապետները պատասխանեցին. «Մենք բացի կայսրից ուրիշ թագավոր չունենք»։","16":"Այն ժամանակ Հիսուսին նրանց ձեռքը հանձնեց, որ խաչը հանվի։ Արդ նրանք վերցրին Հիսուսին ու տարան։","17":"Նա ինքն էր խաչը վերցրել և գնում էր այն տեղը, որ Գագաթ էր կոչվում, որ եբրայերեն Գողգոթա է կոչվում։","18":"Այնտեղ նրան խաչը հանեցին և նրա հետ՝ ևս երկու հոգու՝ այս և այն կողմից, իսկ Հիսուսին՝ մեջտեղում։","19":"Պիղատոսը մի տախտակի վրա գրեց և դրեց խաչի վրա. գրված էր՝ «ՀԻՍՈՒՍ ՆԱԶՈՎՐԵՑԻ, ՀՐԵԱՆԵՐԻ ԹԱԳԱՎՈՐ»։","20":"Այդ տախտակը հրեաներից շատերը կարդացին, որովհետև այն տեղը, որտեղ Հիսուսը խաչը հանվեց, քաղաքին մոտ էր, իսկ տախտակի վրա գրված էր եբրայերեն, հունարեն ու լատիներեն։","21":"Արդ հրեաների քահանայապետները Պիղատոսին ասացին. «Մի՛ գրիր \"Հրեաների թագավոր\", այլ ինչպես նա ասաց. \"Հրեաների թագավորն եմ\"»։","22":"Պիղատոսը պատասխանեց. «Ինչ գրեցի, գրեցի»։","23":"Երբ զինվորները Հիսուսին խաչը հանեցին, վերցրին նրա հագուստները և չորս մասի բաժանեցին. յուրաքանչյուր զինվորին՝ մի մաս։ Վերցրին նաև պատմուճանը, որն առանց կարի էր, վերևից ներքև ամբողջովին գործված։","24":"Արդ նրանք միմյանց ասացին. «Եկեք այն չպատռենք, այլ վրան վիճակ գցենք, որպեսզի տեսնենք, թե ո՛ւմ կընկնի». որպեսզի կատարվի գրվածը, որ ասում է. «Իմ հագուստներն իրենց մեջ բաժանեցին և իմ պատմուճանի վրա վիճակ գցեցին» (Սաղ. 22.18)։ Եվ զինվորներն արեցին այդ բանը։","25":"Հիսուսի խաչի մոտ կանգնած էին նրա մայրը, նրա մորաքույրը՝ Մարիամը՝ Կղեովպասի կինը, և Մարիամ Մագդաղենացին։","26":"Երբ Հիսուսը տեսավ իր մորն ու նրա կողքին կանգնած իր սիրելի աշակերտին, մորն ասաց. «Ո՛վ կին, ահա քո որդին»։","27":"Ապա աշակերտին ասաց. «Ահա քո մայրը»։ Եվ այդ պահից աշակերտը նրան իր մոտ վերցրեց։","28":"Դրանից հետո Հիսուսը, իմանալով, որ ամեն ինչ արդեն կատարված է, որպեսզի իրականանա գրվածը, ասաց. «Ծարավ եմ»։","29":"Այնտեղ քացախով լի մի աման կար. նրանք քացախով մի սպունգ թրջեցին և եղեգի ծայրին դրած՝ նրա բերանին մոտեցրին։","30":"Երբ Հիսուսը քացախը բերանն առավ, ասաց. «Կատարված է»։ Նա գլուխը խոնարհեց և հոգին ավանդեց։","31":"Իսկ հրեաները, քանի որ ուրբաթ օր էր, և որպեսզի մարմինները շաբաթ օրը խաչի վրա չմնային, որովհետև այդ շաբաթը մեծ տոն էր, Պիղատոսին խնդրեցին, որ նրանց սրունքները կոտրեն ու նրանց վերցնեն։","32":"Արդ զինվորները եկան, կոտրեցին առաջինի սրունքները, ապա նրա հետ խաչը հանված մյուսինը։","33":"Բայց երբ Հիսուսի մոտ եկան, տեսան, որ նա արդեն մեռած էր, և նրա սրունքները չկոտրեցին։","34":"Զինվորներից մեկը գեղարդով խոցեց նրա կողը, և իսկույն արյուն ու ջուր դուրս ելավ։","35":"Եվ սա տեսնողը վկայեց, և նրա վկայությունը ճշմարիտ է, ու նա գիտի, որ ճշմարիտ է ասում, որպեսզի դուք ևս հավատաք։","36":"Այս բաները տեղի ունեցան, որպեսզի իրականանա գրվածը. «Նրա ոսկորը չպիտի փշրվի» (Ելք 12.46, Թվ. 9.12, Սաղ. 34.20)։","37":"Եվ մեկ այլ գրված ասում է. «Պիտի նայեն նրան, որին խոցեցին» (Զաք. 12.10)։","38":"Դրանից հետո Հովսեփը, որ Արիմաթեայից էր և հրեաներից վախի պատճառով Հիսուսի ծպտյալ աշակերտը, Պիղատոսին խնդրեց, որ վերցնի Հիսուսի մարմինը։ Եվ Պիղատոսը թույլ տվեց։ Արդ Հովսեփը եկավ և վերցրեց Հիսուսի մարմինը։","39":"Եկավ նաև Նիկոդեմոսը, որը սկզբում գիշերով էր Հիսուսի մոտ եկել, և հալվեի հետ խառնված մոտ հարյուր լիտր զմուռս բերեց։","40":"Նրանք վերցրին Հիսուսի մարմինը և հրեաների սովորության համաձայն՝ այն խնկերով ու կտավներով պատեցին։","41":"Խաչելության վայրում մի պարտեզ կար, պարտեզում՝ մի նոր գերեզման, որտեղ երբեք ոչ ոք չէր դրվել։","42":"Քանի որ հրեաների տոնի նախօրեն էր, և գերեզմանն էլ մոտ էր, Հիսուսին այնտեղ դրեցին։"},"20":{"1":"Շաբաթվա առաջին օրն արշալույսին՝ դեռ լույսը չբացված, Մարիամ Մագդաղենացին եկավ գերեզման և տեսավ, որ քարը գերեզմանից վերցված է։","2":"Այդժամ նա վազեց ու գնաց Սիմոն Պետրոսի և այն մյուս աշակերտի մոտ, որին Հիսուսը սիրում էր։ Եվ նրանց ասաց. «Տիրոջը գերեզմանից վերցրել են, ու չգիտենք, թե որտե՛ղ են նրան դրել»։","3":"Այդժամ Պետրոսն ու մյուս աշակերտը դուրս եկան և գերեզման գնացին։","4":"Երկուսը միասին վազում էին, բայց մյուս աշակերտը Պետրոսից ավելի արագ վազեց և առաջինը գերեզման հասավ։","5":"Նա դեպի ներս կռացավ և կտավներն այնտեղ դրված տեսավ, բայց ներս չմտավ։","6":"Ապա նրա հետևից հասավ Սիմոն Պետրոսը, գերեզման մտավ ու կտավներն այնտեղ դրված տեսավ։","7":"Իսկ վարշամակը, որ Հիսուսի գլխին էր, կտավների հետ չէր, այլ առանձին տեղում էր ծալված դրված։","8":"Այդ ժամանակ ներս մտավ նաև մյուս աշակերտը, որ առաջինն էր գերեզման հասել. տեսավ ու հավատաց։","9":"Որովհետև դեռ չէին հասկացել գրվածը. «Նա մեռելներից հարություն պիտի առնի»։","10":"Աշակերտները դարձյալ տուն գնացին։","11":"Բայց Մարիամը դրսում, գերեզմանի մոտ կանգնած, լալիս էր։ Մինչ լաց էր լինում, ներս կռացավ դեպի գերեզմանը։","12":"Եվ տեսավ երկու հրեշտակների՝ սպիտակ զգեստներով նստած այնտեղ, որտեղ Հիսուսի մարմինն էր դրված. մեկը՝ գլխի կողմում, մյուսը՝ ոտքերի։","13":"Եվ նրանք ասացին նրան. «Ո՛վ կին, ինչո՞ւ ես լալիս»։ Նրանց ասաց. «Որովհետև իմ Տիրոջը վերցրել են, ու չգիտեմ, թե որտե՛ղ են դրել նրան»։","14":"Երբ այս ասաց, հետ շրջվեց ու տեսավ Հիսուսին կանգնած, սակայն չհասկացավ, որ Հիսուսն է։","15":"Հիսուսն ասաց նրան. «Կի՛ն, ինչո՞ւ ես լալիս, ո՞ւմ ես փնտրում»։ Իսկ նա, կարծելով, թե պարտիզպանն է, ասաց. «Տե՛ր, եթե դու ես նրան վերցրել, ասա՛ ինձ՝ որտե՛ղ ես դրել նրան, որպեսզի վերցնեմ»։","16":"Հիսուսն ասաց նրան. «Մարիա՛մ»։ Նա շրջվեց ու եբրայերեն ասաց. «Ռաբբո՛ւնի», որ «Վարդապետ» է նշանակում։","17":"Հիսուսն ասաց նրան. «Ինձ մի՛ մոտեցիր, քանի որ դեռ Հորս մոտ չեմ բարձրացել. բայց դու իմ եղբայրների մո՛տ գնա ու ասա՛ նրանց. \"Ես իմ Հոր և ձեր Հոր մոտ եմ բարձրանում, իմ Աստծու և ձեր Աստծու մոտ\"»։","18":"Մարիամ Մագդաղենացին եկավ և աշակերտներին պատմեց, որ ինքը տեսել է Տիրոջը, և որ նա իրեն այս բաներն է ասել։","19":"Նույն օրը՝ շաբաթվա առաջին օրվա երեկոյան, երբ հրեաներից վախի պատճառով աշակերտները հավաքվել էին մի տեղ և դռները փակել, Հիսուսը եկավ, նրանց մեջտեղում կանգնեց և ասաց նրանց. «Խաղաղությո՜ւն ձեզ»։","20":"Եվ այս ասելով՝ նրանց իր ձեռքերն ու կողը ցույց տվեց։ Աշակերտներն ուրախացան, որ Տիրոջը տեսան։","21":"Հիսուսը դարձյալ ասաց նրանց. «Խաղաղությո՜ւն ձեզ. ինչպես իմ Հայրն ինձ ուղարկեց, այնպես էլ ես եմ ձեզ ուղարկում»։","22":"Այս ասելուց հետո նրանց վրա փչեց ու ասաց. «Առե՛ք Սուրբ Հոգին։","23":"Եթե մեկի մեղքերը ներեք, նրան ներված կլինի. եթե մեկի մեղքերը չներեք, չներված կմնա»։","24":"Բայց Թովմասը՝ տասներկուսից մեկը, «Երկվորյակ» կոչվածը, նրանց հետ չէր, երբ Հիսուսը եկավ։","25":"Մյուս աշակերտները նրան ասացին. «Տիրոջը տեսանք»։ Իսկ նա նրանց ասաց. «Եթե նրա ձեռքերի վրա մեխերի նշանը չտեսնեմ ու իմ մատը մեխերի տեղերը չդնեմ և իմ ձեռքը նրա կողի մեջ չխրեմ, չեմ հավատա»։","26":"Ութ օր հետո աշակերտները դարձյալ ներսում էին. նրանց հետ էր նաև Թովմասը։ Հիսուսը մտավ փակ դռներով, նրանց մեջտեղում կանգնեց և ասաց. «Խաղաղությո՜ւն ձեզ»։","27":"Հետո Թովմասին ասաց. «Բե՛ր քո մատը այստեղ և տե՛ս իմ ձեռքերը, բե՛ր քո ձեռքը և իմ կողի մե՛ջ խրիր. մի՛ երկմտիր, այլ հավատա՛»։","28":"Թովմասը պատասխանեց ու ասաց նրան. «Դու իմ Տերն ես և իմ Աստվածը»։","29":"Հիսուսը նրան ասաց. «Հավատացիր, քանի որ տեսար ինձ. երանի՜ նրանց, ովքեր կհավատան առանց տեսնելու»։","30":"Հիսուսն իր աշակերտների առաջ ուրիշ շատ հրաշքներ էլ գործեց, որոնք այս գրքում գրված չեն։","31":"Բայց սրանք գրվեցին, որպեսզի հավատաք, որ Հիսուսն է Քրիստոսը՝ Աստծու Որդին, և որպեսզի հավատաք ու նրա անունով հավիտենական կյանք ունենաք։"},"21":{"1":"Դրանից հետո Հիսուսը Տիբերիայի լճի ափին դարձյալ հայտնվեց իր աշակերտներին։ Եվ հայտնվեց այսպես։","2":"Սիմոն Պետրոսը, Թովմասը՝ «Երկվորյակ» կոչվածը, Նաթանայելը, որ Գալիլեայի Կանա քաղաքից էր, Զեբեդեոսի որդիները և աշակերտներից ևս երկուսը միասին էին։","3":"Սիմոն Պետրոսն ասաց նրանց. «Գնում եմ ձուկ որսալու»։ Նրան ասացին. «Մենք էլ ենք քեզ հետ գալիս»։ Նրանք ելան և նավ մտան, բայց այդ գիշեր ոչինչ չբռնեցին։","4":"Երբ արդեն առավոտ էր, Հիսուսը լճափին կանգնած էր, սակայն աշակերտները նրան չճանաչեցին։","5":"Այդժամ Հիսուսն ասաց նրանց. «Տղանե՛ր, արդյոք ուտելու բան ունե՞ք»։ Նրան պատասխանեցին. «Ո՛չ»։","6":"Իսկ նա ասաց նրանց. «Ուռկանը նավի աջ կո՛ղմը գցեք և կգտնեք»։ Նրանք գցեցին և ձկների առատությունից չէին կարողանում այն դուրս քաշել։","7":"Արդ այն աշակերտը, որին Հիսուսը սիրում էր, Պետրոսին ասաց. «Տե՛րն է»։ Սիմոն Պետրոսը հենց լսեց, որ Տերն է, հագուստն իր վրա գցեց, որովհետև մերկ էր, և ջրի մեջ նետվեց։","8":"Իսկ մյուս աշակերտները, ձկներով ուռկանը քաշելով, նավակով եկան, քանի որ ցամաքից հեռու էին մոտ երկու հարյուր կանգուն։","9":"Երբ ցամաք ելան, տեսան վառած ածուխի մի կրակատեղ, վրան՝ ձուկ ու հաց դրված։","10":"Հիսուսն ասաց նրանց. «Բերե՛ք այն ձկներից, որ հիմա որսացիք»։","11":"Այդժամ Սիմոն Պետրոսը նավ մտավ և ցամաք հանեց ուռկանը՝ հարյուր հիսուներեք հատ մեծ-մեծ ձկներով լեցուն։ Թեև այդքան ձուկ կար, բայց ուռկանը չպատռվեց։","12":"Հիսուսն ասաց նրանց. «Եկեք ճաշե՛ք»։ Եվ աշակերտներից ոչ ոք չէր համարձակվում հարցնել՝ «Դու ո՞վ ես», որովհետև գիտեին, որ Տերն է։","13":"Հիսուսը եկավ, վերցրեց հացն ու նրանց տվեց, նույնպես և ձուկը։","14":"Այս երրորդ անգամն էր, որ մեռելներից հարություն առնելուց հետո Հիսուսը երևաց իր աշակերտներին։","15":"Երբ ճաշեցին, Հիսուսը Սիմոն Պետրոսին ասաց. «Սիմո՛ն, Հովնանի՛ որդի, սիրո՞ւմ ես ինձ ավելի, քան դրանք»։ Պետրոսը նրան ասաց. «Այո՛, Տե՛ր, դու գիտես, որ ես քեզ սիրում եմ»։ Նրան ասաց. «Արածեցրո՛ւ իմ գառներին»։","16":"Երկրորդ անգամ նրան հարցրեց. «Սիմո՛ն, Հովնանի՛ որդի, սիրո՞ւմ ես ինձ»։ Պետրոսը նրան պատասխանեց. «Այո՛, Տե՛ր, դու գիտես, որ ես քեզ սիրում եմ»։ Նրան ասաց. «Արածեցրո՛ւ իմ ոչխարներին»։","17":"Երրորդ անգամ հարցրեց նրան. «Սիմո՛ն, Հովնանի՛ որդի, սիրո՞ւմ ես ինձ»։ Պետրոսը տրտմեց, որ երրորդ անգամ հարցրեց իրեն՝ «Սիրո՞ւմ ես ինձ»։ Եվ պատասխանեց նրան. «Տե՛ր, դու ամեն ինչ գիտես. դու գիտես, որ ես քեզ սիրում եմ»։ Հիսուսն ասաց նրան. «Արածեցրո՛ւ իմ ոչխարներին։","18":"Ճշմարիտ, ճշմարիտ եմ ասում քեզ. երբ դու երիտասարդ էիր, ինքդ էիր գոտիդ կապում և գնում էիր, ուր որ կամենայիր. բայց երբ ծերանաս, ձեռքերդ կբարձրացնես, և ուրիշը գոտիդ կկապի ու քեզ կտանի այնտեղ, ուր որ չես կամենա»։","19":"Այս ասաց՝ ցույց տալով, թե ինչպիսի՛ մահով նա պիտի փառավորի Աստծուն։ Այս ասելուց հետո ասաց նրան. «Արի՛ իմ հետևից»։","20":"Ապա Պետրոսը շրջվեց և տեսավ, որ իրենց հետևից գալիս է այն աշակերտը, որին Հիսուսը սիրում էր, և որն ընթրիքի ժամանակ նրա կրծքովն էր ընկել ու ասել. «Տե՛ր, ո՞վ է, որ մատնելու է քեզ»։","21":"Պետրոսը, նրան տեսնելով, Հիսուսին ասաց. «Տե՛ր, իսկ սրա՞ն ինչ է լինելու»։","22":"Հիսուսը նրան ասաց. «Եթե ես կամենում եմ, որ դա մնա, մինչև որ ես գամ, քեզ դրանից ի՞նչ. դու արի՛ իմ հետևից»։","23":"Եվ այս խոսքը տարածվեց եղբայրների մեջ, թե իբր այդ աշակերտը չի մեռնելու։ Բայց Հիսուսը չասաց նրան, թե չի մեռնելու, այլ՝ «Եթե կամենում եմ, որ դա մնա, մինչև որ ես գամ, քեզ դրանից ի՞նչ»։","24":"Սա այն աշակերտն է, որ վկայում է այս բաների մասին, և որն էլ դրանք գրեց, ու գիտենք, որ նրա վկայությունը ճշմարիտ է։","25":"Բայց ուրիշ շատ բաներ էլ կան, որ Հիսուսն արեց, որոնք եթե մեկ առ մեկ գրված լինեին, կարծում եմ, թե աշխարհն էլ բավական չէր լինի այդ գրքերը պարփակելու։"}};
